window.FAQ=(window.FAQ||[]).concat([
 {id:'vzx-001',thema:'verzekeringen',vraag:'Wie moet verzekeringnemer zijn bij een ORV voor samenwoners zonder samenlevingscontract?',antwoord:`Bij ongehuwd samenwonenden is een kruislingse opzet vaak gunstig. Ieder is verzekeringnemer en premiebetaler op het leven van de ander. Zo valt de uitkering in de regel niet onder de erfbelasting. Leg vast wie de premie feitelijk betaalt en vanaf welke rekening.`,tags:['orv','samenwonen','kruislings','erfbelasting'],bron:'Successiewet 1956'},
 {id:'vzx-002',thema:'verzekeringen',vraag:'Wat gebeurt er fiscaal als de premie van een kruislingse ORV van een gezamenlijke rekening komt?',antwoord:`Dan kan de Belastingdienst stellen dat de overledene een deel van de premie heeft betaald. Voor dat deel kan de uitkering onder de erfbelasting vallen. Adviseer premiebetaling vanaf de eigen rekening van de verzekeringnemer. Leg dit advies vast in het dossier.`,tags:['orv','kruislings','premiebetaling','erfbelasting'],bron:'Successiewet 1956'},
 {id:'vzx-003',thema:'verzekeringen',vraag:'Hoe werkt de erfbelasting over een ORV bij gehuwden in gemeenschap van goederen?',antwoord:`Bij een gemeenschap van goederen wordt de premie geacht voor de helft door ieder te zijn betaald. Bij een ORV op één leven valt dan in de regel de helft van de uitkering onder de erfbelasting. De verkrijger kan de partnervrijstelling benutten. Raadpleeg voor de actuele vrijstelling de Belastingdienst.`,tags:['orv','gemeenschap van goederen','erfbelasting','partnervrijstelling'],bron:'Successiewet 1956'},
 {id:'vzx-004',thema:'verzekeringen',vraag:'Waarom is een tweelevenpolis minder gunstig dan twee kruislingse polissen?',antwoord:`Een tweelevenpolis keert uit bij het eerste overlijden en vervalt daarna. De overblijvende partner is dan onverzekerd en moet opnieuw medisch worden geaccepteerd. Bij ongehuwden kan de uitkering bovendien deels onder de erfbelasting vallen. Twee kruislingse polissen bieden meer flexibiliteit, maar kunnen meer premie kosten.`,tags:['orv','tweelevenpolis','kruislings'],bron:''},
 {id:'vzx-005',thema:'verzekeringen',vraag:'Moet een ORV op het leven van de ex-partner na een scheiding worden aangepast?',antwoord:`Ja, beoordeel dit altijd. Controleer wie verzekeringnemer, verzekerde en begunstigde zijn. Na de scheiding kan de begunstiging niet meer aansluiten bij de nieuwe situatie. Stem af met het echtscheidingsconvenant en leg de gemaakte keuzes vast.`,tags:['orv','scheiding','begunstiging','convenant'],bron:''},
 {id:'vzx-006',thema:'verzekeringen',vraag:'Wat is het verschil tussen verzekeringnemer, verzekerde en begunstigde bij een ORV?',antwoord:`De verzekeringnemer sluit de polis af en is contractpartij. De verzekerde is degene op wiens leven de verzekering loopt. De begunstigde ontvangt de uitkering. Deze rollen bepalen samen de fiscale gevolgen en wie zeggenschap heeft over de polis.`,tags:['orv','verzekeringnemer','verzekerde','begunstigde'],bron:'BW boek 7'},
 {id:'vzx-007',thema:'verzekeringen',vraag:'Kan een begunstiging onherroepelijk worden?',antwoord:`Ja, als de begunstigde de aanwijzing aanvaardt en dit aan de verzekeraar is meegedeeld. De verzekeringnemer kan de begunstiging dan niet meer eenzijdig wijzigen. Bij verpanding aan een geldverstrekker speelt dit vaak mee. Controleer de status bij de verzekeraar voordat je wijzigingen adviseert.`,tags:['orv','begunstiging','aanvaarding'],bron:'BW boek 7'},
 {id:'vzx-008',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij de begunstigingsclausule?',antwoord:`Een veelgemaakte fout is een standaardclausule die niet past bij de gezinssituatie. Denk aan een ex-partner die nog begunstigde is. Of aan kinderen die bij de uitkering minderjarig zijn zonder regeling voor het beheer. Neem de begunstiging bij iedere herijking door.`,tags:['orv','begunstiging','fouten','herijking'],bron:''},
 {id:'vzx-009',thema:'verzekeringen',vraag:'Wat gebeurt er als minderjarige kinderen begunstigd zijn?',antwoord:`De uitkering valt dan onder het bewind van de wettelijk vertegenwoordiger. Dat is lang niet altijd gewenst. Een testament met een bewindsregeling kan dit sturen. Verwijs de klant naar een notaris en leg die verwijzing vast.`,tags:['orv','minderjarigen','begunstiging','notaris'],bron:''},
 {id:'vzx-010',thema:'verzekeringen',vraag:'Hoe bereken je een ORV-dekking op basis van het tekort in netto besteedbaar inkomen?',antwoord:`Bepaal eerst het inkomen van de nabestaande na overlijden. Zet daar de vaste lasten en gewenste uitgaven tegenover. Het jaarlijkse tekort over de gewenste periode bepaalt de benodigde dekking. Houd rekening met nabestaandenpensioen, Anw en eventuele overige voorzieningen.`,tags:['orv','berekening','nabestaanden','inkomen'],bron:''},
 {id:'vzx-011',thema:'verzekeringen',vraag:'Rekenvoorbeeld: welk deel van de hypotheek dek je met een ORV als de nabestaande een deel kan dragen?',antwoord:`Stel de hypotheek is 300.000 euro en de nabestaande kan zelf 200.000 euro blijven dragen. Dan is een dekking van 100.000 euro het minimum om de woonlasten betaalbaar te houden. Toets dit aan de inkomensgegevens na overlijden. Leg de berekening en uitgangspunten vast in het dossier.`,tags:['orv','rekenvoorbeeld','hypotheek','dekking'],bron:''},
 {id:'vzx-012',thema:'verzekeringen',vraag:'Waarom moet een ORV aansluiten op de aflossingsvorm van de hypotheek?',antwoord:`Bij een annuïteitenhypotheek daalt de schuld eerst langzaam en later sneller. Bij een lineaire hypotheek daalt de schuld gelijkmatig. Een dalende ORV die niet aansluit kan in sommige jaren te weinig dekking geven. Vergelijk het dekkingsverloop met het schuldverloop.`,tags:['orv','aflossingsvorm','dekkingsverloop'],bron:''},
 {id:'vzx-013',thema:'verzekeringen',vraag:'Is een ORV nodig bij een aflossingsvrije hypotheek uit de periode voor 2013?',antwoord:`Juist dan kan een ORV belangrijk zijn, omdat de schuld niet daalt. De nabestaande moet de volledige lening blijven dragen. Kijk naar het inkomen na overlijden en eventuele andere voorzieningen. Leg de afweging vast, ook als de klant afziet van dekking.`,tags:['orv','aflossingsvrij','overgangsrecht'],bron:''},
 {id:'vzx-014',thema:'verzekeringen',vraag:'Hoe ga je om met een ORV bij oversluiten van de hypotheek?',antwoord:`Beoordeel of de bestaande ORV nog past bij de nieuwe schuld en looptijd. Zeg een bestaande polis niet op voordat een nieuwe polis is geaccepteerd. Een nieuwe polis kan duurder zijn door hogere leeftijd of gewijzigde gezondheid. Leg de vergelijking vast.`,tags:['orv','oversluiten','acceptatie'],bron:''},
 {id:'vzx-015',thema:'verzekeringen',vraag:'Waarom mag je een oude ORV niet te snel laten beëindigen?',antwoord:`Bij een nieuwe aanvraag volgt een nieuwe gezondheidsbeoordeling. Is de gezondheid verslechterd, dan kan de klant worden afgewezen of een toeslag krijgen. Zonder dekking loopt de klant dan risico. Laat de oude polis pas stoppen na acceptatie van de nieuwe.`,tags:['orv','beeindigen','gezondheid','acceptatie'],bron:''},
 {id:'vzx-016',thema:'verzekeringen',vraag:'Wat is het vergeetrecht bij een ORV?',antwoord:`Ex-kankerpatiënten hoeven onder voorwaarden een eerdere kankerdiagnose niet meer te melden bij het aanvragen van een ORV. Er geldt een termijn na afronding van de behandeling zonder terugkeer van de ziekte. Voor diagnoses op jonge leeftijd en sommige tumorsoorten zijn kortere termijnen vastgelegd. Controleer de actuele regeling en de voorwaarden van de verzekeraar.`,tags:['orv','vergeetrecht','gezondheidsverklaring'],bron:'Besluit vergeetrecht'},
 {id:'vzx-017',thema:'verzekeringen',vraag:'Mag een verzekeraar bij een ORV vragen naar erfelijkheidsonderzoek?',antwoord:`Onder de vragengrens mag niet worden gevraagd naar de uitkomst van erfelijkheidsonderzoek. Boven die grens gelden andere regels. Het bedrag van de vragengrens wordt periodiek aangepast. Raadpleeg het actuele bedrag bij het Verbond van Verzekeraars of de verzekeraar.`,tags:['orv','erfelijkheid','vragengrens','keuring'],bron:'Wet op de medische keuringen'},
 {id:'vzx-018',thema:'verzekeringen',vraag:'Wat moet je doen als een klant twijfelt wat hij moet melden op de gezondheidsverklaring?',antwoord:`Leg uit dat de klant zelf de vragen naar waarheid moet beantwoorden. Adviseer om bij twijfel te melden. Een adviseur mag de antwoorden niet invullen of sturen. Leg vast dat je de mededelingsplicht en de gevolgen hebt toegelicht.`,tags:['orv','mededelingsplicht','gezondheidsverklaring'],bron:'BW boek 7'},
 {id:'vzx-019',thema:'verzekeringen',vraag:'Wat zijn de gevolgen van een schending van de mededelingsplicht bij een ORV?',antwoord:`De verzekeraar kan de uitkering verlagen naar de verhouding tussen betaalde en verschuldigde premie. Had de verzekeraar de polis bij kennis van de feiten niet gesloten, dan kan uitkering vervallen. Bij opzet tot misleiding vervalt het recht op uitkering. De verzekeraar moet wel tijdig na ontdekking op de schending wijzen.`,tags:['orv','mededelingsplicht','gevolgen'],bron:'BW boek 7'},
 {id:'vzx-020',thema:'verzekeringen',vraag:'Hoe ga je om met een aanvraag die met een premieopslag wordt geaccepteerd?',antwoord:`Bespreek de opslag en de reden daarvan met de klant. Vergelijk zo mogelijk met andere verzekeraars. Leg vast welke keuze de klant maakt en waarom. Bij afwijzing kan de klant soms terecht bij een regeling voor verhoogde risico's.`,tags:['orv','premieopslag','acceptatie','verhoogd risico'],bron:''},
 {id:'vzx-021',thema:'verzekeringen',vraag:'Wat doe je als een klant bij meerdere verzekeraars is afgewezen voor een ORV?',antwoord:`Verken of een gespecialiseerde verzekeraar of een regeling voor verhoogde risico's mogelijk is. Bekijk ook alternatieven, zoals een lagere dekking of andere zekerheden. Bespreek de gevolgen voor de financiering. Leg de afwijzingen en de afweging vast.`,tags:['orv','afwijzing','alternatieven'],bron:''},
 {id:'vzx-022',thema:'verzekeringen',vraag:'Kan een geldverstrekker een ORV verplicht stellen?',antwoord:`Ja, een geldverstrekker kan dit als acceptatievoorwaarde opnemen. Dat komt bijvoorbeeld voor bij een hoge financiering ten opzichte van de woningwaarde. De voorwaarden verschillen per geldverstrekker. Controleer de voorwaarden van de geldverstrekker.`,tags:['orv','geldverstrekker','acceptatievoorwaarde'],bron:''},
 {id:'vzx-023',thema:'verzekeringen',vraag:'Wat betekent verpanding van een ORV voor de nabestaande?',antwoord:`Bij verpanding kan de geldverstrekker de uitkering inzetten voor aflossing van de schuld. Het restant komt toe aan de begunstigde. Zonder aflossing blijven de woonlasten na overlijden gelijk. Leg uit welke keuze er is en wat het effect is op de woonlasten.`,tags:['orv','verpanding','aflossing','nabestaanden'],bron:''},
 {id:'vzx-024',thema:'verzekeringen',vraag:'Mag de uitkering van een verpande ORV voor iets anders worden gebruikt dan aflossing?',antwoord:`Dat hangt af van de pandakte en de geldverstrekker. Vaak moet de geldverstrekker toestemming geven. Soms kan een deel worden uitgekeerd aan de begunstigde. Controleer de voorwaarden van de geldverstrekker.`,tags:['orv','verpanding','pandakte','uitkering'],bron:''},
 {id:'vzx-025',thema:'verzekeringen',vraag:'Wat gebeurt er met een ORV-uitkering als de hypotheek boetevrij kan worden afgelost?',antwoord:`Aflossing na overlijden is bij veel geldverstrekkers boetevrij. De voorwaarden verschillen. Controleer in de hypotheekvoorwaarden of aflossing uit een overlijdensuitkering boetevrij is. Bespreek ook of de nabestaande liever een deel aanhoudt.`,tags:['orv','aflossing','boeterente'],bron:''},
 {id:'vzx-026',thema:'verzekeringen',vraag:'Waarom is de looptijd van een ORV een bewuste keuze?',antwoord:`Een te korte looptijd laat later een risico open. Een te lange looptijd kost onnodig premie. Koppel de looptijd aan de periode waarin nabestaanden de lasten niet kunnen dragen. Denk aan het moment dat kinderen zelfstandig zijn of de schuld voldoende is gedaald.`,tags:['orv','looptijd','premie'],bron:''},
 {id:'vzx-027',thema:'verzekeringen',vraag:'Wat is het risico van een ORV die eindigt voor de hypotheek is afgelost?',antwoord:`Na einde van de ORV is er geen overlijdensdekking meer. Als de schuld dan nog hoog is, kan de nabestaande in de problemen komen. Toets het restschuldrisico op de einddatum. Leg vast waarom voor deze einddatum is gekozen.`,tags:['orv','einddatum','looptijd','risico'],bron:''},
 {id:'vzx-028',thema:'verzekeringen',vraag:'Hoe werkt een premiebetaling die korter is dan de looptijd van de ORV?',antwoord:`Bij een kortere premiebetalingsduur betaalt de klant hogere premies in een kortere periode. De dekking loopt daarna door. Dit kan passen als het inkomen later daalt, bijvoorbeeld na pensionering. Vergelijk de totale premie bij beide varianten.`,tags:['orv','premieduur','looptijd'],bron:''},
 {id:'vzx-029',thema:'verzekeringen',vraag:'Wat is het verschil tussen een gelijkblijvende en een stijgende premie bij een ORV?',antwoord:`Bij een gelijkblijvende premie betaalt de klant elk jaar hetzelfde. Bij een stijgende premie start de premie laag en loopt deze op met de leeftijd. Op lange looptijd kan een stijgende premie duurder uitvallen. Laat de klant de premieverloop over de hele looptijd zien.`,tags:['orv','premie','premieverloop'],bron:''},
 {id:'vzx-030',thema:'verzekeringen',vraag:'Hoe ga je om met een ORV bij een DGA met een hypotheek bij de eigen BV?',antwoord:`Bepaal wie het risico loopt bij overlijden: de nabestaanden, de BV of beide. Verzekeringnemer, begunstigde en premiebetaler moeten passen bij dat risico. De fiscale gevolgen verschillen per opzet. Laat de opzet toetsen door een fiscalist en leg dit vast.`,tags:['orv','dga','bv','fiscaal'],bron:''},
 {id:'vzx-031',thema:'verzekeringen',vraag:'Wat is een compagnonsverzekering?',antwoord:`Een compagnonsverzekering is een ORV tussen ondernemers. Bij overlijden van een vennoot krijgen de anderen geld om het aandeel van de erfgenamen over te nemen. De polis moet aansluiten op de afspraken in het vennootschapscontract of de aandeelhoudersovereenkomst. Controleer bij wijzigingen in waarde of samenstelling of de dekking nog past.`,tags:['orv','compagnon','ondernemers','overname'],bron:''},
 {id:'vzx-032',thema:'verzekeringen',vraag:'Wanneer is een sleutelfiguurverzekering relevant?',antwoord:`Een sleutelfiguurverzekering dekt het financiële verlies van een onderneming bij overlijden van een belangrijke persoon. Denk aan omzetverlies of kosten van vervanging. De onderneming is meestal verzekeringnemer en begunstigde. Laat de fiscale behandeling toetsen.`,tags:['orv','sleutelfiguur','ondernemers'],bron:''},
 {id:'vzx-033',thema:'verzekeringen',vraag:'Valt een ORV-uitkering onder de inkomstenbelasting?',antwoord:`Een uitkering uit een zuivere ORV is in de regel niet belast in box 1. De uitkering kan wel onder de erfbelasting vallen. Na ontvangst telt het geld mee als vermogen in box 3. Controleer bijzondere situaties, zoals polissen in een onderneming.`,tags:['orv','inkomstenbelasting','box 3'],bron:'Wet IB 2001'},
 {id:'vzx-034',thema:'verzekeringen',vraag:'Heeft een lopende ORV waarde voor box 3?',antwoord:`Een zuivere risicoverzekering zonder opbouw heeft in de regel geen waarde in box 3. Dat komt doordat er geen afkoopwaarde is. Bij polissen met opbouw kan dat anders zijn. Controleer de polisvorm.`,tags:['orv','box 3','afkoopwaarde'],bron:'Wet IB 2001'},
 {id:'vzx-035',thema:'verzekeringen',vraag:'Wat moet je vastleggen bij het advies over de hoogte van een ORV?',antwoord:`Leg de uitgangspunten vast: inkomen na overlijden, gewenste woonlasten en periode. Vermeld welke voorzieningen al aanwezig zijn, zoals nabestaandenpensioen. Leg vast welke dekking je adviseert en welke de klant kiest. Noteer bij afwijking de reden en de besproken risico's.`,tags:['orv','dossier','vastlegging'],bron:'Wft'},
 {id:'vzx-036',thema:'verzekeringen',vraag:'Hoe verwerk je het nabestaandenpensioen bij de ORV-berekening?',antwoord:`Vraag het actuele overzicht van het nabestaandenpensioen op bij de pensioenuitvoerder. Let op of het om een opbouw- of risicobasis gaat. Bij risicobasis vervalt de dekking vaak bij einde dienstverband. Neem dat risico mee in de berekening.`,tags:['orv','nabestaandenpensioen','risicobasis'],bron:''},
 {id:'vzx-037',thema:'verzekeringen',vraag:'Wat is het risico van een nabestaandenpensioen op risicobasis?',antwoord:`De dekking geldt alleen zolang de deelnemer in dienst is. Bij ontslag of baanwisseling kan de dekking vervallen. Soms is vrijwillige voortzetting mogelijk. Bespreek dit risico en leg vast of een aanvullende ORV is overwogen.`,tags:['nabestaandenpensioen','risicobasis','baanwisseling'],bron:'Pensioenwet'},
 {id:'vzx-038',thema:'verzekeringen',vraag:'Hoe ga je om met een ORV bij een samengesteld gezin?',antwoord:`Breng in kaart welke kinderen van wie zijn en wie wat moet ontvangen. De wettelijke erfopvolging kan anders uitpakken dan de klant verwacht. Stem de begunstiging af op het testament. Verwijs zo nodig naar een notaris.`,tags:['orv','samengesteld gezin','begunstiging','testament'],bron:''},
 {id:'vzx-039',thema:'verzekeringen',vraag:'Kan een ORV worden afgesloten op het leven van iemand zonder diens toestemming?',antwoord:`Nee, in de praktijk vragen verzekeraars de handtekening en gezondheidsverklaring van de verzekerde. De verzekerde moet instemmen met de verzekering op zijn leven. Dat geldt ook bij een kruislingse opzet. Leg de toestemming vast.`,tags:['orv','toestemming','verzekerde'],bron:''},
 {id:'vzx-040',thema:'verzekeringen',vraag:'Wat gebeurt er met een ORV als de verzekeringnemer eerder overlijdt dan de verzekerde?',antwoord:`De polis valt dan in de nalatenschap van de verzekeringnemer. De erfgenamen worden verzekeringnemer, tenzij anders is geregeld. Dat speelt vooral bij kruislingse polissen. Een opvolgend verzekeringnemer in de polis kan dit voorkomen.`,tags:['orv','verzekeringnemer','nalatenschap','kruislings'],bron:''},
 {id:'vzx-041',thema:'verzekeringen',vraag:'Waarom is de premievrije waarde bij een ORV meestal nul?',antwoord:`Een zuivere ORV bouwt geen kapitaal op. Stopt de premiebetaling, dan stopt de dekking meestal. Soms is er bij gelijkblijvende premie tijdelijk een kleine reserve. Controleer de voorwaarden van de verzekeraar.`,tags:['orv','premievrij','afkoop'],bron:''},
 {id:'vzx-042',thema:'verzekeringen',vraag:'Hoe lang heeft een klant dekking als de ORV-premie niet wordt betaald?',antwoord:`De verzekeraar moet na de vervaldatum eerst aanmanen. Pas na het verstrijken van de termijn in de aanmaning kan de dekking worden geschorst of beëindigd. De precieze gevolgen staan in de voorwaarden. Controleer de voorwaarden van de verzekeraar.`,tags:['orv','premieachterstand','aanmaning'],bron:'BW boek 7'},
 {id:'vzx-043',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij het vergelijken van ORV-offertes?',antwoord:`Alleen naar de premie kijken is een veelgemaakte fout. Let ook op dekkingsverloop, premieduur en voorwaarden zoals uitsluitingen. Vergelijk offertes met dezelfde uitgangspunten. Leg de vergelijking vast in het dossier.`,tags:['orv','offertes','vergelijken','fouten'],bron:''},
 {id:'vzx-044',thema:'verzekeringen',vraag:'Zijn er uitsluitingen bij een ORV waar je op moet letten?',antwoord:`Ja, bijvoorbeeld voor bepaalde risicovolle sporten of beroepen. Ook zelfdoding kan in de eerste periode na ingang zijn uitgesloten. Molest en atoomkernreacties zijn vaak beperkt gedekt. Controleer de voorwaarden van de verzekeraar en bespreek relevante uitsluitingen.`,tags:['orv','uitsluitingen','polisvoorwaarden'],bron:''},
 {id:'vzx-045',thema:'verzekeringen',vraag:'Moet een klant een nieuwe hobby melden aan de ORV-verzekeraar?',antwoord:`Na ingang van de polis geldt in de regel geen plicht om nieuwe hobby's te melden, tenzij de voorwaarden dat vragen. De mededelingsplicht geldt vooral bij het aangaan. Bij verhoging van de dekking geldt deze opnieuw. Controleer de voorwaarden van de verzekeraar.`,tags:['orv','mededelingsplicht','wijziging'],bron:''},
 {id:'vzx-046',thema:'verzekeringen',vraag:'Hoe ga je om met een ORV bij emigratie van de verzekerde?',antwoord:`Veel ORV-polissen blijven bij verhuizing naar het buitenland doorlopen. Sommige verzekeraars stellen beperkingen. De fiscale behandeling kan veranderen. Controleer de voorwaarden van de verzekeraar en het belastingrecht van het nieuwe woonland.`,tags:['orv','emigratie','buitenland'],bron:''},
 {id:'vzx-047',thema:'verzekeringen',vraag:'Kan een ORV worden verhoogd zonder nieuwe medische beoordeling?',antwoord:`Soms biedt een polis een optie om bij bepaalde gebeurtenissen te verhogen zonder nieuwe gezondheidsbeoordeling. Denk aan huwelijk, geboorte of aankoop van een woning. Dit geldt alleen binnen de grenzen van de voorwaarden. Controleer de voorwaarden van de verzekeraar.`,tags:['orv','verhoging','gebeurtenisoptie'],bron:''},
 {id:'vzx-048',thema:'verzekeringen',vraag:'Wat doe je als een klant een ORV wil zonder dat de partner het weet?',antwoord:`Bespreek het doel en de gevolgen voor de begunstiging en de erfbelasting. Je hebt een zorgplicht tegenover je eigen klant. Als de partner verzekerde is, is diens medewerking nodig. Leg het gesprek en de gemaakte keuzes zorgvuldig vast.`,tags:['orv','zorgplicht','partner'],bron:'Wft'},
 {id:'vzx-049',thema:'verzekeringen',vraag:'Hoe gaat de uitkering van een ORV in zijn werk na overlijden?',antwoord:`De begunstigde of nabestaanden melden het overlijden bij de verzekeraar. De verzekeraar vraagt een akte van overlijden en gegevens van de begunstigde. Soms is een verklaring van erfrecht nodig. Begeleid de nabestaanden en controleer of verpanding geldt.`,tags:['orv','uitkering','overlijden','schadebehandeling'],bron:''},
 {id:'vzx-050',thema:'verzekeringen',vraag:'Hoe documenteer je dat een klant bewust kiest voor een lagere ORV-dekking dan geadviseerd?',antwoord:`Leg het geadviseerde bedrag en het gekozen bedrag naast elkaar vast. Beschrijf het concrete gevolg voor de nabestaanden, bijvoorbeeld het maandelijkse tekort. Noteer de reden van de klant in diens eigen woorden. Laat de klant het verslag bevestigen.`,tags:['orv','afwijken advies','dossier'],bron:'Wft'},
 {id:'vzx-051',thema:'verzekeringen',vraag:'Hoe bepaal je het juiste verzekerde bedrag bij een AOV voor een zelfstandige?',antwoord:`Ga uit van de netto besteedbare behoefte en reken terug naar een bruto bedrag. De AOV-uitkering is belast, de premie is in de regel aftrekbaar. Verzeker niet meer dan de verzekeraar accepteert op basis van het aantoonbare inkomen. Leg de berekening vast.`,tags:['aov','verzekerd bedrag','zzp','berekening'],bron:'Wet IB 2001'},
 {id:'vzx-052',thema:'verzekeringen',vraag:'Welk inkomen accepteert een verzekeraar als basis voor een AOV?',antwoord:`Verzekeraars kijken meestal naar de gemiddelde winst uit onderneming over enkele jaren. Bij starters gelden vaak aparte regels of maximale bedragen. De verzekeraar kan bij schade alsnog het werkelijke inkomen toetsen. Controleer de voorwaarden van de verzekeraar.`,tags:['aov','inkomen','acceptatie','starters'],bron:''},
 {id:'vzx-053',thema:'verzekeringen',vraag:'Wat gebeurt er als een AOV is afgesloten op een te hoog verzekerd bedrag?',antwoord:`Bij schade kan de verzekeraar de uitkering beperken tot het werkelijk gederfde inkomen. Dat geldt bij polissen met een inkomenstoets of anticumulatie. De klant heeft dan te veel premie betaald. Herijk het verzekerde bedrag periodiek.`,tags:['aov','oververzekering','inkomenstoets'],bron:''},
 {id:'vzx-054',thema:'verzekeringen',vraag:'Wat is het verschil tussen een sommenverzekering en een schadeverzekering bij AOV?',antwoord:`Bij een sommenverzekering keert de verzekeraar het afgesproken bedrag uit naar het arbeidsongeschiktheidspercentage. Bij een schadeverzekering is het werkelijke inkomensverlies de basis. Dat heeft invloed op de uitkering bij wisselend inkomen. Controleer de voorwaarden van de verzekeraar.`,tags:['aov','sommenverzekering','schadeverzekering'],bron:''},
 {id:'vzx-055',thema:'verzekeringen',vraag:'Waarom is de minimale arbeidsongeschiktheidsgrens bij een AOV belangrijk?',antwoord:`Veel polissen keren pas uit vanaf een bepaald percentage arbeidsongeschiktheid. Onder die grens ontvangt de klant niets. Bij gedeeltelijke uitval kan dat een groot gat geven. Vergelijk deze grens tussen offertes en bespreek het effect.`,tags:['aov','ao-percentage','drempel'],bron:''},
 {id:'vzx-056',thema:'verzekeringen',vraag:'Hoe werkt een uitkering bij gedeeltelijke arbeidsongeschiktheid in een AOV?',antwoord:`Vaak keert de verzekeraar uit naar rato van het arbeidsongeschiktheidspercentage. Boven een hoger percentage volgt meestal volledige uitkering. Rekenvoorbeeld: bij 50 procent arbeidsongeschiktheid en een verzekerd bedrag van 40.000 euro is de uitkering 20.000 euro per jaar. Controleer de klassen en grenzen in de voorwaarden.`,tags:['aov','gedeeltelijk','rekenvoorbeeld','uitkering'],bron:''},
 {id:'vzx-057',thema:'verzekeringen',vraag:'Wat betekent een eigen risicotermijn van één jaar bij een AOV in de praktijk?',antwoord:`De klant moet het eerste jaar van arbeidsongeschiktheid zelf overbruggen. Dat vraagt een buffer of een andere voorziening. De premie is lager dan bij een korte wachttijd. Toets of de klant die periode financieel aankan en leg dit vast.`,tags:['aov','wachttijd','buffer'],bron:''},
 {id:'vzx-058',thema:'verzekeringen',vraag:'Waarom is de eindleeftijd van een AOV een aandachtspunt?',antwoord:`Een lage eindleeftijd verlaagt de premie, maar laat een gat tot de AOW-leeftijd. De AOW-leeftijd kan stijgen. Een polis die eerder eindigt, dekt de laatste werkzame jaren niet. Bespreek dit gat en leg de keuze vast.`,tags:['aov','eindleeftijd','aow-leeftijd'],bron:''},
 {id:'vzx-059',thema:'verzekeringen',vraag:'Wat is een herzieningsrecht of premieherzieningsclausule bij een AOV?',antwoord:`Sommige polissen geven de verzekeraar het recht om premie of voorwaarden aan te passen voor een groep verzekerden. De klant kan daardoor later meer gaan betalen. Bespreek dit risico bij het advies. Controleer de voorwaarden van de verzekeraar.`,tags:['aov','premieherziening','voorwaarden'],bron:''},
 {id:'vzx-060',thema:'verzekeringen',vraag:'Wat is het risico van een AOV met een uitsluiting voor rugklachten?',antwoord:`Bij uitval door rugklachten volgt dan geen uitkering. Rugklachten zijn een veelvoorkomende oorzaak van uitval bij fysieke beroepen. De dekking is dan feitelijk beperkt. Bespreek de uitsluiting expliciet en leg vast dat de klant de gevolgen begrijpt.`,tags:['aov','uitsluiting','medisch','acceptatie'],bron:''},
 {id:'vzx-061',thema:'verzekeringen',vraag:'Kan een uitsluiting op een AOV later worden heroverwogen?',antwoord:`Sommige verzekeraars heroverwegen een uitsluiting na een klachtenvrije periode. Dat gebeurt meestal op verzoek en met medische informatie. Er is geen recht op opheffing. Zet een reminder in het dossier voor een herbeoordeling.`,tags:['aov','uitsluiting','herbeoordeling'],bron:''},
 {id:'vzx-062',thema:'verzekeringen',vraag:'Hoe ga je om met een beroepswijziging van een klant met een AOV?',antwoord:`Een beroepswijziging kan de premie en de dekking beïnvloeden. De verzekeraar moet de wijziging vaak worden gemeld. Bij beroepsarbeidsongeschiktheid is het verzekerde beroep van groot belang. Controleer de voorwaarden en leg de melding vast.`,tags:['aov','beroepswijziging','melding'],bron:''},
 {id:'vzx-063',thema:'verzekeringen',vraag:'Wat is het verschil tussen eigen beroep en beroepsgebonden passende arbeid?',antwoord:`Bij eigen beroep kijkt de verzekeraar alleen naar het verzekerde beroep. Bij beroepsgebonden passende arbeid kan ook ander werk passend zijn dat aansluit bij opleiding en ervaring. Een uitkering is bij de tweede definitie sneller beperkt. Vergelijk de definities tussen offertes.`,tags:['aov','eigen beroep','passende arbeid','criterium'],bron:''},
 {id:'vzx-064',thema:'verzekeringen',vraag:'Wat is gangbare arbeid bij een AOV?',antwoord:`Bij gangbare arbeid toetst de verzekeraar of de klant nog algemeen geaccepteerd werk kan doen. Dat is de ruimste toets en de goedkoopste dekking. De kans op uitkering is kleiner. Leg vast dat de klant het verschil met eigen beroep begrijpt.`,tags:['aov','gangbare arbeid','criterium'],bron:''},
 {id:'vzx-065',thema:'verzekeringen',vraag:'Hoe verandert de dekking als een AOV na enkele jaren van eigen beroep naar passende arbeid gaat?',antwoord:`Sommige polissen kennen een combinatie. Eerst geldt beroepsarbeidsongeschiktheid en na een periode passende of gangbare arbeid. Na die overgang kan de uitkering dalen of stoppen. Controleer de voorwaarden van de verzekeraar en bespreek het moment van overgang.`,tags:['aov','criterium','combinatie'],bron:''},
 {id:'vzx-066',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij het adviseren van een AOV aan een zzp-er?',antwoord:`Een veelgemaakte fout is alleen kijken naar de premie. Criterium, wachttijd, eindleeftijd en uitsluitingen bepalen de waarde van de dekking. Ook het ontbreken van een buffer voor de wachttijd wordt vaak gemist. Leg de afwegingen per onderdeel vast.`,tags:['aov','zzp','fouten','advies'],bron:''},
 {id:'vzx-067',thema:'verzekeringen',vraag:'Hoe vergelijk je een AOV met een Broodfonds en een vangnetregeling?',antwoord:`Vergelijk duur, hoogte en zekerheid van de uitkering. Een Broodfonds biedt een beperkte periode op basis van schenkingen. Een AOV kan tot de eindleeftijd doorlopen. Leg vast welke combinatie de klant kiest en welk risico overblijft.`,tags:['aov','broodfonds','vergelijken'],bron:''},
 {id:'vzx-068',thema:'verzekeringen',vraag:'Kan een zelfstandige zich vrijwillig verzekeren bij UWV?',antwoord:`Ja, onder voorwaarden kan een zelfstandige een vrijwillige verzekering bij UWV afsluiten. Er gelden termijnen waarbinnen dat moet. De uitkering volgt de systematiek van de werknemersverzekeringen. Controleer de actuele voorwaarden bij UWV.`,tags:['aov','uwv','vrijwillige verzekering','zzp'],bron:'UWV'},
 {id:'vzx-069',thema:'verzekeringen',vraag:'Wat moet je weten over een wettelijke AOV voor zelfstandigen?',antwoord:`Er wordt gewerkt aan een wettelijke basisverzekering voor zelfstandigen. Inhoud en invoeringsdatum zijn nog niet definitief. Volg de actuele wetgeving en communicatie van de overheid. Leg in het dossier vast dat dit is besproken.`,tags:['aov','basisverzekering','zzp','wetgeving'],bron:''},
 {id:'vzx-070',thema:'verzekeringen',vraag:'Is de uitkering van een AOV belast?',antwoord:`Ja, de periodieke uitkering is belast in box 1. Daar staat tegenover dat de premie in de regel aftrekbaar is als uitgave voor een inkomensvoorziening. Betaalde de klant de premie niet als aftrekpost, dan kan dat anders liggen. Laat bijzondere situaties fiscaal toetsen.`,tags:['aov','fiscaal','uitkering','box 1'],bron:'Wet IB 2001'},
 {id:'vzx-071',thema:'verzekeringen',vraag:'Hoe gaat een AOV om met de premie tijdens arbeidsongeschiktheid?',antwoord:`Veel polissen kennen premievrijstelling naar rato van de arbeidsongeschiktheid. De klant betaalt dan minder of geen premie. De precieze regeling verschilt. Controleer de voorwaarden van de verzekeraar.`,tags:['aov','premievrijstelling'],bron:''},
 {id:'vzx-072',thema:'verzekeringen',vraag:'Wat is indexatie bij een AOV?',antwoord:`Bij indexatie stijgt de verzekerde uitkering jaarlijks, vóór of tijdens uitkering. Dat beschermt tegen inflatie. Indexatie verhoogt de premie. Bespreek of de klant indexatie vóór uitkering, tijdens uitkering of beide wil. Leg de keuze vast.`,tags:['aov','indexatie','inflatie'],bron:''},
 {id:'vzx-073',thema:'verzekeringen',vraag:'Hoe verhoudt een AOV zich tot de hypotheek van een zelfstandige?',antwoord:`Bij arbeidsongeschiktheid vallen inkomsten weg, maar de woonlasten lopen door. Toets of de uitkering samen met andere inkomsten de lasten dekt. Neem de wachttijd mee in de buffer. Leg de berekening en de keuze van de klant vast.`,tags:['aov','hypotheek','zzp','woonlasten'],bron:''},
 {id:'vzx-074',thema:'verzekeringen',vraag:'Wat is een AOV met een uitkeringsduur van een beperkt aantal jaren?',antwoord:`Zo een polis keert maximaal een vast aantal jaren uit per schadegeval. Daarna stopt de uitkering, ook als de klant arbeidsongeschikt blijft. De premie is lager. Bespreek het risico van langdurige uitval en leg vast.`,tags:['aov','uitkeringsduur','korte dekking'],bron:''},
 {id:'vzx-075',thema:'verzekeringen',vraag:'Hoe ga je om met een AOV voor een DGA?',antwoord:`Een DGA is vaak niet verplicht verzekerd voor de werknemersverzekeringen. Daardoor ontbreekt een wettelijk vangnet. De AOV kan op naam van de DGA of via de BV worden geregeld. De fiscale gevolgen verschillen, laat dit toetsen.`,tags:['aov','dga','bv','werknemersverzekeringen'],bron:''},
 {id:'vzx-076',thema:'verzekeringen',vraag:'Wat doet een verzekeraar bij de schadebeoordeling van een AOV?',antwoord:`De verzekeraar laat een medisch adviseur of verzekeringsarts de beperkingen vaststellen. Daarna beoordeelt een arbeidsdeskundige wat de klant nog kan. Samen bepalen zij het arbeidsongeschiktheidspercentage. De klant kan een second opinion of herbeoordeling vragen.`,tags:['aov','schadebehandeling','arbeidsdeskundige'],bron:''},
 {id:'vzx-077',thema:'verzekeringen',vraag:'Welke rol heeft de adviseur bij een AOV-claim?',antwoord:`De adviseur helpt bij de melding en de communicatie met de verzekeraar. Hij bewaakt termijnen en controleert of de beoordeling volgens de voorwaarden gaat. Medische gegevens deelt de klant rechtstreeks met de medisch adviseur. Leg contactmomenten en afspraken vast.`,tags:['aov','claim','rol adviseur','schadebehandeling'],bron:''},
 {id:'vzx-078',thema:'verzekeringen',vraag:'Waarom moet arbeidsongeschiktheid tijdig worden gemeld bij de AOV-verzekeraar?',antwoord:`De wachttijd begint vaak pas te lopen na melding of vanaf een vastgestelde datum. Te late melding kan de uitkering vertragen. De verzekeraar kan bovendien in zijn belangen worden geschaad. Adviseer melding zodra uitval langer lijkt te duren.`,tags:['aov','melding','wachttijd'],bron:'BW boek 7'},
 {id:'vzx-079',thema:'verzekeringen',vraag:'Hoe ga je om met een AOV als de klant van zzp-er werknemer wordt?',antwoord:`Als werknemer heeft de klant wettelijke dekking via de WIA. De AOV kan dan overbodig of te ruim zijn. Sommige polissen bieden een premievrije voortzetting of mogelijkheid tot herstart. Bespreek opzeggen pas na beoordeling van de nieuwe situatie.`,tags:['aov','overstap','werknemer','wia'],bron:''},
 {id:'vzx-080',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij het opzeggen van een AOV?',antwoord:`Een veelgemaakte fout is opzeggen zonder te kijken naar toekomstige behoefte. Een nieuwe polis vraagt later een nieuwe gezondheidsbeoordeling. Dat kan leiden tot uitsluitingen of afwijzing. Leg vast dat de klant deze gevolgen kent.`,tags:['aov','opzeggen','fouten'],bron:''},
 {id:'vzx-081',thema:'verzekeringen',vraag:'Welke dekking biedt een woonlastenverzekering bij arbeidsongeschiktheid?',antwoord:`De verzekering keert een vast maandbedrag uit gedurende een beperkte periode. Er gelden een wachttijd en een maximale uitkeringsduur. Het bedrag is bedoeld voor de woonlasten. Controleer de voorwaarden van de verzekeraar.`,tags:['woonlastenverzekering','arbeidsongeschiktheid','uitkering'],bron:''},
 {id:'vzx-082',thema:'verzekeringen',vraag:'Welke dekking biedt een woonlastenverzekering bij werkloosheid?',antwoord:`Meestal geldt de dekking alleen bij onvrijwillige werkloosheid met recht op een WW-uitkering. Er geldt een wachttijd na ingang van de polis en na het ontslag. De uitkeringsduur is beperkt. Controleer de voorwaarden van de verzekeraar.`,tags:['woonlastenverzekering','werkloosheid','ww'],bron:''},
 {id:'vzx-083',thema:'verzekeringen',vraag:'Waarom is een woonlastenverzekering voor werkloosheid vaak ongeschikt voor zzp-ers?',antwoord:`Werkloosheidsdekking vereist meestal een WW-recht. Zelfstandigen hebben geen WW. De dekking voor werkloosheid is dan niet bruikbaar. Bespreek wat de klant wel nodig heeft en leg vast.`,tags:['woonlastenverzekering','zzp','werkloosheid'],bron:''},
 {id:'vzx-084',thema:'verzekeringen',vraag:'Valt een woonlastenverzekering onder het provisieverbod?',antwoord:`Ja, woonlastenverzekeringen vallen als betalingsbeschermer onder het provisieverbod. De adviseur wordt betaald door de klant. Hij mag geen provisie van de verzekeraar ontvangen. Leg de vergoedingsafspraken vast in de opdracht tot dienstverlening.`,tags:['woonlastenverzekering','provisieverbod','betalingsbeschermer'],bron:'Wft'},
 {id:'vzx-085',thema:'verzekeringen',vraag:'Hoe hoog moet een woonlastenverzekering worden afgesloten?',antwoord:`Ga uit van de bruto of netto woonlasten en het verwachte inkomensverlies. Houd rekening met wat WW, WIA of andere voorzieningen nog dekken. Verzekeraars hanteren een maximum. Leg de berekening vast.`,tags:['woonlastenverzekering','hoogte','berekening'],bron:''},
 {id:'vzx-086',thema:'verzekeringen',vraag:'Wat is het risico als een klant al op de hoogte is van een reorganisatie?',antwoord:`Veel woonlastenverzekeringen sluiten werkloosheid uit als ontslag bij ingang bekend of te verwachten was. De klant moet zulke informatie melden. Een claim kan anders worden afgewezen. Vraag hiernaar en leg het antwoord vast.`,tags:['woonlastenverzekering','reorganisatie','uitsluiting'],bron:''},
 {id:'vzx-087',thema:'verzekeringen',vraag:'Hoe combineer je een woonlastenverzekering met een WGA-hiaatverzekering via de werkgever?',antwoord:`Breng eerst in kaart wat de werkgeversdekking uitkeert. Een woonlastenverzekering kan dan het resterende tekort dekken. Voorkom dubbele dekking voor hetzelfde risico. Leg de afweging vast.`,tags:['woonlastenverzekering','wga-hiaat','werkgever','dubbele dekking'],bron:''},
 {id:'vzx-088',thema:'verzekeringen',vraag:'Wat is de rol van een woonlastenverzekering bij een tijdelijk contract?',antwoord:`Bij een tijdelijk contract is het werkloosheidsrisico vaak groter. Een woonlastenverzekering kan de eerste periode overbruggen. Let op de voorwaarden rond einde contract, die niet altijd gedekt zijn. Controleer de voorwaarden van de verzekeraar.`,tags:['woonlastenverzekering','tijdelijk contract','werkloosheid'],bron:''},
 {id:'vzx-089',thema:'verzekeringen',vraag:'Is een woonlastenverzekering opzegbaar?',antwoord:`Ja, meestal kan de klant de verzekering tussentijds opzeggen. Er kan een opzegtermijn gelden. Bij opnieuw afsluiten gelden wachttijden opnieuw. Bespreek dit voordat de klant opzegt.`,tags:['woonlastenverzekering','opzeggen','wachttijd'],bron:''},
 {id:'vzx-090',thema:'verzekeringen',vraag:'Hoe ga je om met een woonlastenverzekering bij partners met twee inkomens?',antwoord:`Bepaal per partner het effect van uitval op de woonlasten. Omdat het tweede inkomen volledig meetelt in de leennorm, kan de lening sterk op beide inkomens leunen. Uitval van één partner kan dan een groot tekort geven. Bespreek of dekking voor één of beide partners nodig is.`,tags:['woonlastenverzekering','tweeverdieners','leennormen'],bron:'Nibud'},
 {id:'vzx-091',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij woonlastenverzekeringen?',antwoord:`Een veelgemaakte fout is het niet controleren van de dekking voor de beroepssituatie. Denk aan uitzendkrachten, zzp-ers of mensen in proeftijd. De verzekering kan dan voor een deel van de risico's niet werken. Leg de toets op de beroepssituatie vast.`,tags:['woonlastenverzekering','fouten','dekking'],bron:''},
 {id:'vzx-092',thema:'verzekeringen',vraag:'Moet een adviseur een woonlastenverzekering adviseren bij elke hypotheek?',antwoord:`Nee, het advies hangt af van het risico en de overige voorzieningen van de klant. De adviseur moet het risico wel in kaart brengen en bespreken. Als de klant geen dekking wil, leg je dat vast. Een verplichte koppeling met de hypotheek is niet toegestaan.`,tags:['woonlastenverzekering','advies','hypotheek','zorgplicht'],bron:'Wft'},
 {id:'vzx-093',thema:'verzekeringen',vraag:'Hoe toets je of een AOV-uitkering voldoende is voor de woonlasten?',antwoord:`Zet de netto AOV-uitkering naast de netto maandlasten en de overige vaste lasten. Houd rekening met de belasting op de uitkering. Bereken ook de situatie bij gedeeltelijke arbeidsongeschiktheid. Leg de uitkomst vast.`,tags:['aov','woonlasten','toets'],bron:''},
 {id:'vzx-094',thema:'verzekeringen',vraag:'Welke gegevens vraag je op voor een AOV-advies?',antwoord:`Vraag jaarcijfers of aangiften, beroepsomschrijving en bestaande voorzieningen op. Inventariseer buffers en andere inkomensbronnen. Bespreek de risicobereidheid en wensen rond wachttijd en criterium. Leg dit vast in het klantprofiel.`,tags:['aov','inventarisatie','klantprofiel'],bron:'Wft'},
 {id:'vzx-095',thema:'verzekeringen',vraag:'Wat is het verschil tussen een AOV en een ongevallenverzekering?',antwoord:`Een ongevallenverzekering keert alleen uit bij een ongeval. Ziekte is niet gedekt. Een AOV dekt in de regel ziekte en ongeval. Een ongevallenverzekering is geen vervanging van een AOV.`,tags:['aov','ongevallenverzekering','verschil'],bron:''},
 {id:'vzx-096',thema:'verzekeringen',vraag:'Hoe gaat een AOV om met psychische klachten?',antwoord:`Psychische klachten zijn in de regel gedekt. Sommige polissen beperken de uitkeringsduur voor psychische aandoeningen. Bij eerdere klachten kan een uitsluiting worden gemaakt. Controleer de voorwaarden van de verzekeraar.`,tags:['aov','psychisch','beperking'],bron:''},
 {id:'vzx-097',thema:'verzekeringen',vraag:'Wat is een zwangerschaps- en bevallingsuitkering voor zelfstandigen?',antwoord:`Zelfstandigen kunnen bij UWV een uitkering aanvragen rond zwangerschap en bevalling. De hoogte is gekoppeld aan het inkomen met een wettelijk maximum. Een AOV keert hiervoor vaak niet uit. Controleer de actuele regeling bij UWV.`,tags:['zelfstandigen','zwangerschap','uwv'],bron:'Wet arbeid en zorg'},
 {id:'vzx-098',thema:'verzekeringen',vraag:'Hoe gaat een AOV om met inkomen uit andere werkzaamheden tijdens uitkering?',antwoord:`Bij een schadeverzekering kan inkomen uit werk tijdens uitkering worden verrekend. Bij een sommenverzekering is dat vaak niet zo, maar kan het AO-percentage wijzigen. De klant moet wijzigingen melden. Controleer de voorwaarden van de verzekeraar.`,tags:['aov','inkomsten','verrekening'],bron:''},
 {id:'vzx-099',thema:'verzekeringen',vraag:'Waarom is een gezondheidsverklaring bij een AOV uitgebreider dan bij een ORV?',antwoord:`Bij een AOV is het risico op uitval door veelvoorkomende klachten groter. Verzekeraars vragen daarom naar klachten van het bewegingsapparaat en psychische klachten. Dit leidt vaker tot uitsluitingen. Bereid de klant hierop voor en leg de uitleg vast.`,tags:['aov','gezondheidsverklaring','acceptatie'],bron:''},
 {id:'vzx-100',thema:'verzekeringen',vraag:'Hoe leg je vast dat een zzp-er bewust geen AOV afsluit?',antwoord:`Beschrijf het risico concreet: wat gebeurt er met inkomen en woonlasten bij langdurige uitval. Noteer welke alternatieven zijn besproken, zoals buffer, Broodfonds of vangnetregeling. Leg de reden van de klant vast. Laat de klant het adviesverslag bevestigen.`,tags:['aov','zzp','afwijken advies','dossier'],bron:'Wft'},
 {id:'vzx-101',thema:'verzekeringen',vraag:'Wat is het verschil tussen de WGA en de IVA?',antwoord:`De IVA is voor werknemers die volledig en duurzaam arbeidsongeschikt zijn. De WGA is voor werknemers die gedeeltelijk of tijdelijk volledig arbeidsongeschikt zijn. In de IVA is het inkomen stabieler. In de WGA hangt de uitkering af van werk en de fase waarin iemand zit.`,tags:['wia','wga','iva','verschil'],bron:'Wet WIA'},
 {id:'vzx-102',thema:'verzekeringen',vraag:'Wat gebeurt er bij minder dan 35 procent arbeidsongeschiktheid?',antwoord:`Er is dan geen recht op een WIA-uitkering. De werknemer wordt geacht met restverdiencapaciteit verder te werken. Lukt dat niet, dan kan het inkomen sterk dalen. Verzekeringen voor dit risico bestaan, vaak collectief via de werkgever.`,tags:['wia','35-min','inkomensverlies'],bron:'Wet WIA'},
 {id:'vzx-103',thema:'verzekeringen',vraag:'Hoe lang duurt de loongerelateerde WGA-uitkering?',antwoord:`De duur hangt af van het arbeidsverleden. Het minimum is enkele maanden en het maximum is twee jaar. Daarna volgt een loonaanvullingsuitkering of een vervolguitkering. Vraag bij de klant het arbeidsverleden na of laat dit bij UWV opvragen.`,tags:['wga','loongerelateerd','duur'],bron:'Wet WIA'},
 {id:'vzx-104',thema:'verzekeringen',vraag:'Wanneer krijgt iemand een loonaanvullingsuitkering in plaats van een vervolguitkering?',antwoord:`Een loonaanvullingsuitkering volgt als iemand voldoende van de restverdiencapaciteit benut. De wet legt daarvoor een minimumgrens vast. Wie minder of niet werkt, krijgt een vervolguitkering. Die is gebaseerd op het minimumloon en vaak veel lager.`,tags:['wga','loonaanvulling','vervolguitkering'],bron:'Wet WIA'},
 {id:'vzx-105',thema:'verzekeringen',vraag:'Waarom ontstaat het WGA-hiaat vooral in de vervolgfase?',antwoord:`In de vervolgfase is de uitkering gebaseerd op het minimumloon en de arbeidsongeschiktheidsklasse. Het eerder verdiende loon speelt dan geen rol meer. Bij een hoger inkomen ontstaat daardoor een groot verschil. Dat verschil is het WGA-hiaat.`,tags:['wga-hiaat','vervolguitkering'],bron:'Wet WIA'},
 {id:'vzx-106',thema:'verzekeringen',vraag:'Hoe controleer je of een klant via de werkgever een WGA-hiaatverzekering heeft?',antwoord:`Vraag naar de arbeidsvoorwaarden en het personeelshandboek. Vraag ook het pensioenoverzicht en eventuele collectieve verzekeringen op. Een werknemer weet het vaak zelf niet. Leg vast welke documenten je hebt gezien.`,tags:['wga-hiaat','werkgever','inventarisatie'],bron:''},
 {id:'vzx-107',thema:'verzekeringen',vraag:'Wat is het verschil tussen een WGA-hiaat basis en uitgebreid?',antwoord:`Een basisdekking vult de uitkering aan als de werknemer zijn restverdiencapaciteit onvoldoende benut. Een uitgebreide dekking geeft een hogere aanvulling, ook als iemand wel werkt. De precieze dekking verschilt per verzekeraar. Controleer de voorwaarden van de collectieve regeling.`,tags:['wga-hiaat','basis','uitgebreid'],bron:''},
 {id:'vzx-108',thema:'verzekeringen',vraag:'Wat betekent het als de werkgever eigenrisicodrager voor de WGA is?',antwoord:`De werkgever betaalt dan de WGA-uitkering zelf, meestal tot tien jaar. Hij is ook verantwoordelijk voor de re-integratie. Dat staat los van een WGA-hiaatdekking voor de werknemer. Vraag beide punten na bij de werkgever.`,tags:['wga','eigenrisicodrager','werkgever'],bron:'Wet WIA'},
 {id:'vzx-109',thema:'verzekeringen',vraag:'Hoe laat je het inkomensverlies boven het maximum dagloon zien in een rekenvoorbeeld?',antwoord:`Stel dat het loon boven het maximum dagloon uitkomt. De WIA-uitkering wordt berekend over het loon tot dat maximum. Over het meerdere ontvangt de werknemer niets. Een excedentverzekering dekt dat deel. Raadpleeg het actuele maximum dagloon bij UWV.`,tags:['wia-excedent','maximum dagloon','rekenvoorbeeld'],bron:'UWV'},
 {id:'vzx-110',thema:'verzekeringen',vraag:'Wat gebeurt er met de pensioenopbouw bij arbeidsongeschiktheid?',antwoord:`Veel pensioenregelingen kennen premievrije voortzetting bij arbeidsongeschiktheid. De opbouw loopt dan door zonder premiebetaling. Dat geldt naar rato van het percentage. Controleer de pensioenregeling van de werkgever.`,tags:['arbeidsongeschiktheid','pensioen','premievrije voortzetting'],bron:''},
 {id:'vzx-111',thema:'verzekeringen',vraag:'Hoe lang betaalt een werkgever het loon door bij ziekte?',antwoord:`De werkgever betaalt in de regel maximaal 104 weken door. Er gelden wettelijke minimumpercentages. Cao of arbeidscontract kunnen gunstiger zijn. Bij onvoldoende re-integratie kan UWV een loonsanctie opleggen.`,tags:['loondoorbetaling','ziekte','104 weken'],bron:'BW boek 7'},
 {id:'vzx-112',thema:'verzekeringen',vraag:'Wat is een loonsanctie en wat betekent dat voor de werknemer?',antwoord:`Bij onvoldoende re-integratie-inspanning kan UWV de werkgever verplichten langer loon door te betalen. Dat kan tot maximaal een jaar extra. De WIA-beoordeling schuift dan op. Voor de inkomensplanning van de klant is dat relevant.`,tags:['loonsanctie','re-integratie','poortwachter'],bron:'Wet verbetering poortwachter'},
 {id:'vzx-113',thema:'verzekeringen',vraag:'Hoe betrek je de WIA-situatie bij een lopende hypotheekaanvraag?',antwoord:`Bepaal welk inkomen structureel en duurzaam is. Een IVA-uitkering is stabieler dan een WGA-uitkering. Geldverstrekkers hebben eigen regels voor uitkeringsinkomen. Controleer de voorwaarden van de geldverstrekker.`,tags:['wia','hypotheek','uitkering','inkomen'],bron:''},
 {id:'vzx-114',thema:'verzekeringen',vraag:'Wat moet je vastleggen bij het advies over arbeidsongeschiktheid van een werknemer?',antwoord:`Leg vast welke wettelijke en werkgeversvoorzieningen er zijn. Toon het inkomensverloop in de verschillende WIA-fasen. Noteer het tekort ten opzichte van de woonlasten. Leg de keuze van de klant en de reden vast.`,tags:['arbeidsongeschiktheid','dossier','werknemer','wia'],bron:'Wft'},
 {id:'vzx-115',thema:'verzekeringen',vraag:'Welke fasen laat je zien in een arbeidsongeschiktheidsanalyse voor een werknemer?',antwoord:`Laat de loondoorbetalingsperiode zien. Daarna de loongerelateerde WGA-fase en de vervolgfase. Toon ook de IVA-situatie en het scenario onder 35 procent. Zo ziet de klant per fase het tekort.`,tags:['arbeidsongeschiktheid','analyse','fasen'],bron:''},
 {id:'vzx-116',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij een WIA-analyse?',antwoord:`Een veelgemaakte fout is alleen het IVA-scenario tonen. De WGA-vervolgfase en het scenario onder 35 procent geven vaak het grootste tekort. Ook het niet meenemen van werkgeversdekkingen leidt tot een verkeerd beeld. Leg de uitgangspunten van de analyse vast.`,tags:['wia','analyse','fouten'],bron:''},
 {id:'vzx-117',thema:'verzekeringen',vraag:'Kan een WIA-uitkering worden herzien?',antwoord:`Ja, UWV kan het arbeidsongeschiktheidspercentage herbeoordelen. Dat kan op verzoek of op initiatief van UWV. Een wijziging kan de uitkering verhogen of verlagen. Neem dit onzekerheidseffect mee bij een financieringsadvies.`,tags:['wia','herbeoordeling','uwv'],bron:'Wet WIA'},
 {id:'vzx-118',thema:'verzekeringen',vraag:'Wanneer eindigt een WIA-uitkering?',antwoord:`De uitkering eindigt in elk geval bij het bereiken van de AOW-leeftijd. Ook bij herstel tot onder 35 procent eindigt het recht. Bij overlijden vervalt de uitkering. Neem het einde van de uitkering mee in de inkomensplanning.`,tags:['wia','einde','aow-leeftijd'],bron:'Wet WIA'},
 {id:'vzx-119',thema:'verzekeringen',vraag:'Wat is de Ziektewet-vangnetregeling?',antwoord:`De vangnetregeling geldt voor zieke werknemers zonder werkgever of met bijzondere status. Denk aan uitzendkrachten, werknemers met een tijdelijk contract dat afloopt en zieke WW-ers. UWV betaalt dan een Ziektewetuitkering. Daarna kan een WIA-beoordeling volgen.`,tags:['ziektewet','vangnet','flexwerker'],bron:'Ziektewet'},
 {id:'vzx-120',thema:'verzekeringen',vraag:'Hoe gaat het inkomensverlies bij arbeidsongeschiktheid voor een flexwerker?',antwoord:`Een flexwerker valt bij ziekte na einde contract vaak onder de vangnetregeling. Het inkomen is dan lager dan bij een vaste werknemer met aanvulling. Werkgeversdekkingen ontbreken meestal. Breng dit tekort in kaart.`,tags:['flexwerker','arbeidsongeschiktheid','inkomensverlies'],bron:''},
 {id:'vzx-121',thema:'verzekeringen',vraag:'Waarom ontvangt een nabestaande soms wel nabestaandenpensioen maar geen Anw?',antwoord:`Het nabestaandenpensioen volgt uit de pensioenregeling van de overledene en kent geen inkomenstoets. De Anw stelt eisen aan de situatie van de nabestaande, zoals de zorg voor een jong kind of arbeidsongeschiktheid. Ook kan een eigen inkomen de Anw verlagen of laten vervallen. Toets beide voorzieningen daarom apart in de overlijdensanalyse.`,tags:['anw','nabestaandenpensioen','verschil'],bron:'Algemene nabestaandenwet'},
 {id:'vzx-122',thema:'verzekeringen',vraag:'Wordt een ORV-uitkering verrekend met de Anw?',antwoord:`Nee, een uitkering uit een ORV telt niet mee voor de inkomenstoets van de Anw. Inkomen uit arbeid en uitkeringen die daarvoor in de plaats komen wel. Dat maakt een ORV geschikt om een Anw-hiaat aan te vullen. Controleer de actuele regels bij de SVB.`,tags:['anw','orv','inkomenstoets'],bron:'SVB'},
 {id:'vzx-123',thema:'verzekeringen',vraag:'Hoe werkt de inkomenstoets van de Anw?',antwoord:`Inkomen uit werk en uitkeringen in plaats van werk verlagen de Anw-uitkering. Boven een bepaalde grens vervalt de uitkering. Een nabestaandenpensioen wordt niet verrekend. Raadpleeg de actuele bedragen en grenzen bij de SVB.`,tags:['anw','inkomenstoets','svb'],bron:'Algemene nabestaandenwet'},
 {id:'vzx-124',thema:'verzekeringen',vraag:'Heeft een samenwonende partner recht op Anw?',antwoord:`Ja, als er sprake was van een gezamenlijke huishouding en aan de overige voorwaarden is voldaan. De SVB toetst dit. Een samenlevingscontract en gezamenlijk adres helpen als bewijs. Controleer de situatie bij de SVB.`,tags:['anw','samenwonen','gezamenlijke huishouding'],bron:'SVB'},
 {id:'vzx-125',thema:'verzekeringen',vraag:'Wat gebeurt er met de Anw als de nabestaande gaat samenwonen?',antwoord:`Bij samenwonen of hertrouwen stopt de Anw-uitkering. Dat geldt ook bij een nieuwe gezamenlijke huishouding. De nabestaande moet dit melden aan de SVB. Neem dit mee in langetermijnplanning.`,tags:['anw','samenwonen','einde'],bron:'Algemene nabestaandenwet'},
 {id:'vzx-126',thema:'verzekeringen',vraag:'Wanneer heeft een nabestaande met kinderen geen Anw meer?',antwoord:`Zodra het jongste kind 18 wordt, vervalt de Anw voor een nabestaande die alleen op basis van een kind recht had. Dat kan plotseling een groot inkomensverschil geven. Neem deze einddatum op in de analyse. Stem de looptijd van een eventuele ORV hierop af.`,tags:['anw','kinderen','einddatum'],bron:'Algemene nabestaandenwet'},
 {id:'vzx-127',thema:'verzekeringen',vraag:'Hoe bepaal je de looptijd van een Anw-hiaatverzekering?',antwoord:`Koppel de looptijd aan de periode waarin de Anw zou gelden. Bij een jong kind is dat tot het kind 18 jaar wordt. Houd rekening met de inkomenstoets: bij een werkende partner krijgt deze vaak geen Anw. Leg de berekening vast.`,tags:['anw-hiaat','looptijd','berekening'],bron:''},
 {id:'vzx-128',thema:'verzekeringen',vraag:'Is een Anw-hiaatverzekering nuttig als de partner goed verdient?',antwoord:`Bij een goed inkomen van de nabestaande is er door de inkomenstoets vaak geen Anw. Dan valt er geen Anw weg en is er geen hiaat in strikte zin. Er kan wel een inkomenstekort bestaan. Dat dek je dan beter met een ORV of nabestaandenpensioen.`,tags:['anw-hiaat','inkomenstoets','orv'],bron:''},
 {id:'vzx-129',thema:'verzekeringen',vraag:'Wat is een wezenpensioen en hoe verhoudt dit zich tot de Anw?',antwoord:`Een wezenpensioen komt uit de pensioenregeling en wordt uitgekeerd aan kinderen bij overlijden van een ouder. De Anw kent alleen een uitkering voor volle wezen. Bij overlijden van één ouder ontvangen de kinderen dus geen Anw. Controleer het wezenpensioen in de regeling.`,tags:['wezenpensioen','anw','kinderen'],bron:'Algemene nabestaandenwet'},
 {id:'vzx-130',thema:'verzekeringen',vraag:'Heeft een ex-partner recht op nabestaandenpensioen?',antwoord:`Een ex-partner kan recht hebben op een bijzonder nabestaandenpensioen. Dat deel is opgebouwd tijdens het huwelijk of geregistreerd partnerschap. Er kunnen andere afspraken zijn gemaakt bij de scheiding. Controleer de pensioenregeling en het convenant.`,tags:['nabestaandenpensioen','ex-partner','scheiding'],bron:'Pensioenwet'},
 {id:'vzx-131',thema:'verzekeringen',vraag:'Hoe verandert de pensioentransitie het nabestaandenpensioen?',antwoord:`In de nieuwe pensioenregels wordt het nabestaandenpensioen voor overlijden voor pensioendatum vaak op risicobasis geregeld. De dekking kan dan afhangen van het dienstverband. Regelingen verschillen per fonds en verzekeraar. Vraag het actuele overzicht op en controleer de regeling.`,tags:['nabestaandenpensioen','wtp','risicobasis'],bron:'Wet toekomst pensioenen'},
 {id:'vzx-132',thema:'verzekeringen',vraag:'Waarom is de beëindiging van een dienstverband relevant voor de overlijdensdekking?',antwoord:`Bij een nabestaandenpensioen op risicobasis vervalt de dekking vaak bij einde dienstverband. Er kan een korte uitloopperiode gelden. Daarna is de nabestaande onverzekerd. Bespreek dit bij baanwisseling en WW.`,tags:['overlijden','dienstverband','nabestaandenpensioen'],bron:''},
 {id:'vzx-133',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij de Anw-analyse?',antwoord:`Een veelgemaakte fout is de Anw meetellen terwijl de nabestaande door de inkomenstoets niets krijgt. Ook wordt de einddatum bij 18 jaar van het jongste kind vaak gemist. Zo ontstaat een te rooskleurig beeld. Toets het scenario en leg de uitgangspunten vast.`,tags:['anw','analyse','fouten'],bron:''},
 {id:'vzx-134',thema:'verzekeringen',vraag:'Wat gebeurt er met een WW-uitkering bij ziekte?',antwoord:`Bij ziekte tijdens WW gaat de werknemer over naar de Ziektewet. Na langdurige ziekte kan een WIA-beoordeling volgen. De hoogte van de uitkering kan veranderen. Neem dit scenario mee bij werknemers met een onzeker dienstverband.`,tags:['ww','ziektewet','arbeidsongeschiktheid'],bron:'Ziektewet'},
 {id:'vzx-135',thema:'verzekeringen',vraag:'Hoe verwerk je een arbeidsongeschiktheidspensioen in de analyse?',antwoord:`Een arbeidsongeschiktheidspensioen vult de WIA-uitkering aan, vaak boven het maximum dagloon. Soms dekt het ook het WGA-hiaat. Vraag het reglement op en lees de definities goed. Neem alleen dekkingen mee die je in documenten hebt gezien.`,tags:['arbeidsongeschiktheidspensioen','wia-excedent','analyse'],bron:''},
 {id:'vzx-136',thema:'verzekeringen',vraag:'Kan een werknemer zelf een WGA-hiaatverzekering afsluiten?',antwoord:`Ja, er zijn individuele producten op de markt. Ze zijn vaak duurder dan een collectieve regeling. Controleer eerst of de werkgever al dekking biedt. Voorkom dubbele dekking en leg de afweging vast.`,tags:['wga-hiaat','individueel','dubbele dekking'],bron:''},
 {id:'vzx-137',thema:'verzekeringen',vraag:'Hoe ga je om met een klant die al gedeeltelijk arbeidsongeschikt is?',antwoord:`Breng de huidige uitkering en het verwachte verloop in kaart. Nieuwe AO-dekking is voor bestaande klachten meestal uitgesloten. Wees voorzichtig met aannames over herstel. Leg de onzekerheden vast.`,tags:['arbeidsongeschiktheid','bestaande klachten','analyse'],bron:''},
 {id:'vzx-138',thema:'verzekeringen',vraag:'Wat is de restverdiencapaciteit in de WIA?',antwoord:`De restverdiencapaciteit is wat iemand volgens UWV nog kan verdienen. UWV stelt dit vast op basis van functies die passend zijn. Het werkelijke inkomen kan lager zijn. Het verschil bepaalt mede de uitkering in de WGA.`,tags:['wia','restverdiencapaciteit','uwv'],bron:'Wet WIA'},
 {id:'vzx-139',thema:'verzekeringen',vraag:'Waarom is het verschil tussen bruto en netto belangrijk in een AO-analyse?',antwoord:`Uitkeringen zijn belast en vaak lager dan het loon. Het netto tekort kan anders uitvallen dan het bruto verschil. Ook toeslagen en heffingskortingen kunnen veranderen. Reken met netto bedragen en leg de methode vast.`,tags:['arbeidsongeschiktheid','netto','analyse'],bron:''},
 {id:'vzx-140',thema:'verzekeringen',vraag:'Hoe ga je om met een overlijdensanalyse bij een alleenstaande met kinderen?',antwoord:`Na overlijden is er geen partner die de woonlasten draagt. De zorg voor de kinderen moet worden geregeld, vaak via testament en voogdij. Bekijk wezenpensioen en de wens om de kinderen financieel te ondersteunen. Verwijs naar een notaris en leg vast.`,tags:['overlijden','alleenstaande','kinderen','voogdij'],bron:''},
 {id:'vzx-141',thema:'verzekeringen',vraag:'Wat is het effect van overlijden op de toeslagen van de nabestaande?',antwoord:`Bij overlijden verandert het huishoudinkomen en daarmee het recht op toeslagen. Dat kan voordeel of nadeel geven. De nabestaande moet de wijziging doorgeven. Neem dit mee in de analyse zonder vaste bedragen.`,tags:['overlijden','toeslagen','nabestaanden'],bron:'Belastingdienst'},
 {id:'vzx-142',thema:'verzekeringen',vraag:'Hoe adviseer je een ondernemer met personeel over arbeidsongeschiktheid?',antwoord:`Scheid het risico van de ondernemer zelf en het werkgeversrisico. Voor personeel spelen loondoorbetaling, verzuimverzekering en eigenrisicodragerschap. Voor de ondernemer gaat het om een AOV. Leg per risico de afweging vast.`,tags:['ondernemer','personeel','verzuim','aov'],bron:''},
 {id:'vzx-143',thema:'verzekeringen',vraag:'Wat is een verzuimverzekering?',antwoord:`Een verzuimverzekering dekt het risico van loondoorbetaling bij ziekte van personeel. De werkgever is verzekeringnemer. Er is vaak een eigen risico in dagen. Controleer de voorwaarden van de verzekeraar.`,tags:['verzuimverzekering','werkgever','loondoorbetaling'],bron:''},
 {id:'vzx-144',thema:'verzekeringen',vraag:'Waarom is de datum van eerste ziektedag belangrijk?',antwoord:`De eerste ziektedag bepaalt de start van de wachttijd voor de WIA. Ook de looptijd van de loondoorbetaling hangt hiervan af. Bij een AOV en woonlastenverzekering kan de datum de uitkering beïnvloeden. Leg de datum nauwkeurig vast.`,tags:['eerste ziektedag','wachttijd','wia'],bron:''},
 {id:'vzx-145',thema:'verzekeringen',vraag:'Wat doe je als een klant een WIA-beslissing niet eens is?',antwoord:`De klant kan bezwaar maken bij UWV binnen de wettelijke termijn. Een deskundige of jurist kan helpen. De adviseur kan wijzen op de termijn en op het effect voor de financiële planning. Leg vast welke informatie je hebt gegeven.`,tags:['wia','bezwaar','uwv'],bron:'Algemene wet bestuursrecht'},
 {id:'vzx-146',thema:'verzekeringen',vraag:'Hoe werkt een collectieve Anw-hiaatverzekering via de pensioenregeling?',antwoord:`Sommige pensioenregelingen bieden een vrijwillige Anw-hiaatdekking. De werknemer betaalt de premie vaak zelf. De dekking eindigt meestal bij einde dienstverband. Controleer de regeling en de voorwaarden.`,tags:['anw-hiaat','collectief','pensioenregeling'],bron:''},
 {id:'vzx-147',thema:'verzekeringen',vraag:'Hoe presenteer je een overlijdens- en AO-analyse begrijpelijk aan de klant?',antwoord:`Gebruik een tijdlijn met inkomen en lasten per fase. Laat het tekort zien in netto bedragen per maand. Benoem de aannames, zoals huidige wetgeving. Leg vast dat de klant de uitkomsten heeft ontvangen en begrepen.`,tags:['analyse','presentatie','klantcommunicatie'],bron:'Wft'},
 {id:'vzx-148',thema:'verzekeringen',vraag:'Hoe vaak moet een AO- en overlijdensanalyse worden geactualiseerd?',antwoord:`Actualiseer bij belangrijke levensgebeurtenissen, zoals geboorte, scheiding of baanwissel. Ook wijzigingen in wetgeving of pensioenregeling zijn een aanleiding. Een vaste periodieke check helpt dit te borgen. Leg de afspraken vast in de dienstverleningsovereenkomst.`,tags:['analyse','actualisatie','levensgebeurtenis'],bron:''},
 {id:'vzx-149',thema:'verzekeringen',vraag:'Telt de Anw mee als inkomen bij een hypotheekaanvraag?',antwoord:`Een Anw-uitkering is tijdelijk en afhankelijk van voorwaarden. Geldverstrekkers gaan daar verschillend mee om. Vaak telt de uitkering slechts beperkt of niet mee. Controleer de voorwaarden van de geldverstrekker.`,tags:['anw','hypotheek','inkomen'],bron:''},
 {id:'vzx-150',thema:'verzekeringen',vraag:'Wat is het verschil tussen een AO-scenario en een werkloosheidsscenario in de analyse?',antwoord:`Bij werkloosheid geldt de WW met een beperkte duur. Bij arbeidsongeschiktheid volgen loondoorbetaling en WIA. De tekorten verschillen in hoogte en duur. Laat beide scenario's afzonderlijk zien.`,tags:['analyse','ww','arbeidsongeschiktheid'],bron:''},
 {id:'vzx-151',thema:'verzekeringen',vraag:'Rekenvoorbeeld: hoe werkt de evenredigheidsregel bij onderverzekering van een woning?',antwoord:`Stel de herbouwwaarde is 400.000 euro en de verzekerde som 300.000 euro. Dan is 75 procent van de waarde verzekerd. Bij een schade van 100.000 euro keert de verzekeraar dan 75.000 euro uit. Een garantie tegen onderverzekering kan dit voorkomen.`,tags:['opstal','onderverzekering','evenredigheid','rekenvoorbeeld'],bron:'BW boek 7'},
 {id:'vzx-152',thema:'verzekeringen',vraag:'Wat is een garantie tegen onderverzekering bij opstal?',antwoord:`De verzekeraar ziet af van de evenredigheidsregel als de herbouwwaarde op de afgesproken manier is vastgesteld. Dat gebeurt met een herbouwwaardemeter of taxatie. De garantie vervalt vaak bij een verbouwing die niet is gemeld. Controleer de voorwaarden van de verzekeraar.`,tags:['opstal','garantie onderverzekering','herbouwwaarde'],bron:''},
 {id:'vzx-153',thema:'verzekeringen',vraag:'Moet een klant een verbouwing melden aan de opstalverzekeraar?',antwoord:`Ja, bij een verbouwing of uitbouw kan de herbouwwaarde stijgen. Zonder melding kan onderverzekering ontstaan. Ook tijdens de verbouwing kunnen beperkingen gelden. Adviseer de klant de verbouwing vooraf te melden.`,tags:['opstal','verbouwing','melding','herbouwwaarde'],bron:''},
 {id:'vzx-154',thema:'verzekeringen',vraag:'Is er dekking voor een woning die tijdelijk leegstaat?',antwoord:`Bij leegstand gelden vaak beperkingen, zoals voor inbraak of waterschade. Na een bepaalde periode kan de dekking verder worden ingeperkt. Dit speelt bijvoorbeeld bij een oude woning die te koop staat. Controleer de voorwaarden en meld leegstand tijdig.`,tags:['opstal','leegstand','oude woning'],bron:''},
 {id:'vzx-155',thema:'verzekeringen',vraag:'Wat moet je regelen voor de opstal van de oude woning bij dubbele woonlasten?',antwoord:`Zorg dat de oude woning verzekerd blijft tot de overdracht. Meld eventuele leegstand aan de verzekeraar. Bij verhuur gelden andere voorwaarden. Leg vast dat je de klant hierop hebt gewezen.`,tags:['opstal','oude woning','overbrugging','leegstand'],bron:''},
 {id:'vzx-156',thema:'verzekeringen',vraag:'Is de opstal verzekerd vanaf het moment van het tekenen van de koopakte?',antwoord:`Het risico gaat in de regel over bij de juridische levering bij de notaris. Vanaf dat moment moet de koper verzekerd zijn. De geldverstrekker eist een opstalverzekering bij de hypotheek. Regel de ingangsdatum op de leveringsdatum.`,tags:['opstal','ingangsdatum','levering'],bron:''},
 {id:'vzx-157',thema:'verzekeringen',vraag:'Waarom eist de geldverstrekker een opstalverzekering?',antwoord:`De woning is het onderpand voor de lening. Bij schade moet de waarde van het onderpand worden hersteld. Daarom eist de geldverstrekker een passende opstalverzekering. Controleer de voorwaarden van de geldverstrekker.`,tags:['opstal','geldverstrekker','onderpand'],bron:''},
 {id:'vzx-158',thema:'verzekeringen',vraag:'Wat is het verschil tussen herbouwwaarde en herstelwaarde?',antwoord:`Herbouwwaarde is wat nodig is om de woning volledig opnieuw te bouwen. Bij gedeeltelijke schade gaat het om de kosten van herstel. Verzekeraars vergoeden schade meestal op basis van herstel of herbouw. Lees de schaderegeling in de voorwaarden.`,tags:['opstal','herbouwwaarde','herstel'],bron:''},
 {id:'vzx-159',thema:'verzekeringen',vraag:'Wat gebeurt er als de klant na brand niet herbouwt?',antwoord:`Veel voorwaarden vergoeden dan niet de herbouwwaarde maar een lagere waarde. Dat kan de verkoopwaarde zijn als die lager is. Er kunnen termijnen gelden waarbinnen herbouw moet starten. Controleer de voorwaarden van de verzekeraar.`,tags:['opstal','brand','niet herbouwen','schaderegeling'],bron:''},
 {id:'vzx-160',thema:'verzekeringen',vraag:'Hoe zit het met opstal bij een monumentale woning?',antwoord:`Herbouw van een monument is vaak duurder door eisen aan materialen en vakmanschap. Een standaard herbouwwaardemeter is dan ongeschikt. Een taxatie is meestal nodig. Controleer of de verzekeraar monumenten accepteert en onder welke voorwaarden.`,tags:['opstal','monument','taxatie'],bron:''},
 {id:'vzx-161',thema:'verzekeringen',vraag:'Is schade door overstroming gedekt op de opstalpolis?',antwoord:`Overstroming door het bezwijken van primaire waterkeringen is in de regel uitgesloten. Veel polissen dekken wel overstroming door secundaire keringen of hevige neerslag. De dekking verschilt per verzekeraar. Controleer de voorwaarden en bespreek dit met de klant.`,tags:['opstal','overstroming','waterkering'],bron:''},
 {id:'vzx-162',thema:'verzekeringen',vraag:'Wat is de Wet tegemoetkoming schade bij rampen?',antwoord:`Deze wet biedt de overheid een basis om bij rampen een tegemoetkoming te geven. Het gaat om schade die niet redelijkerwijs verzekerbaar is. Er is geen recht op volledige vergoeding. Een tegemoetkoming wordt per situatie vastgesteld.`,tags:['rampen','overstroming','tegemoetkoming'],bron:'Wet tegemoetkoming schade bij rampen'},
 {id:'vzx-163',thema:'verzekeringen',vraag:'Hoe werkt stormdekking op een opstalpolis?',antwoord:`Veel voorwaarden hanteren een definitie van storm met een minimale windsnelheid. Schade door lagere windsnelheden is dan niet als stormschade gedekt. Bij stormschade geldt vaak een eigen risico. Controleer de definitie in de voorwaarden.`,tags:['opstal','storm','definitie'],bron:''},
 {id:'vzx-164',thema:'verzekeringen',vraag:'Is schade door achterstallig onderhoud gedekt?',antwoord:`Nee, schade door slecht onderhoud is meestal uitgesloten. Denk aan lekkage door een versleten dak. De verzekeraar kijkt naar de oorzaak van de schade. Wijs de klant op onderhoud als voorwaarde voor dekking.`,tags:['opstal','onderhoud','uitsluiting'],bron:''},
 {id:'vzx-165',thema:'verzekeringen',vraag:'Wat is het verschil tussen een uitgebreide en een all-risk opstaldekking?',antwoord:`Bij uitgebreid zijn alleen de genoemde gebeurtenissen gedekt. Bij all-risk is ook plotselinge en onvoorziene schade van buitenaf gedekt, behalve uitsluitingen. All-risk is duurder. Vergelijk de uitsluitingen nauwkeurig.`,tags:['opstal','inboedel','all-risk','uitgebreid'],bron:''},
 {id:'vzx-166',thema:'verzekeringen',vraag:'Wie verzekert de opstal bij een appartementsrecht met een VvE?',antwoord:`De VvE verzekert meestal het gebouw collectief. De eigenaar verzekert zelf de inboedel en eventuele verbeteringen. Controleer de splitsingsakte en de polis van de VvE. Leg vast welke onderdelen bij de eigenaar liggen.`,tags:['opstal','vve','appartement','splitsingsakte'],bron:''},
 {id:'vzx-167',thema:'verzekeringen',vraag:'Wat is eigenaarsbelang bij een appartement?',antwoord:`Eigenaarsbelang zijn verbeteringen die de eigenaar zelf heeft aangebracht, zoals een nieuwe keuken. De VvE-polis dekt die vaak niet. Ze kunnen worden meeverzekerd op de inboedelpolis. Controleer de VvE-polis en de inboedelvoorwaarden.`,tags:['inboedel','eigenaarsbelang','appartement','vve'],bron:''},
 {id:'vzx-168',thema:'verzekeringen',vraag:'Wat is huurdersbelang?',antwoord:`Huurdersbelang zijn verbeteringen die een huurder heeft aangebracht in de huurwoning. Denk aan een keuken of vloer. Deze kunnen op de inboedelpolis worden verzekerd. Vaak geldt een maximum.`,tags:['inboedel','huurdersbelang'],bron:''},
 {id:'vzx-169',thema:'verzekeringen',vraag:'Hoe bepaal je de inboedelwaarde?',antwoord:`Gebruik een inboedelwaardemeter of laat een taxatie doen. Vaak is de garantie tegen onderverzekering gekoppeld aan de meter. Kostbaarheden zoals sieraden en kunst vragen aparte aandacht. Leg de vastgestelde waarde vast.`,tags:['inboedel','waardebepaling','inboedelwaardemeter'],bron:''},
 {id:'vzx-170',thema:'verzekeringen',vraag:'Wat is het verschil tussen nieuwwaarde en dagwaarde bij inboedel?',antwoord:`Bij nieuwwaarde vergoedt de verzekeraar het bedrag om een nieuw vergelijkbaar voorwerp te kopen. Bij dagwaarde gaat de verzekeraar uit van nieuwwaarde min waardevermindering. Veel voorwaarden vergoeden dagwaarde bij oude of sterk afgeschreven zaken. Controleer de voorwaarden van de verzekeraar.`,tags:['inboedel','nieuwwaarde','dagwaarde'],bron:''},
 {id:'vzx-171',thema:'verzekeringen',vraag:'Waarom zijn maxima voor kostbaarheden een aandachtspunt?',antwoord:`Voor sieraden, elektronica of kunst gelden vaak aparte maxima. Een klant met veel kostbaarheden kan onvoldoende verzekerd zijn. Soms is een aparte kostbaarhedenverzekering nodig. Inventariseer dit en leg de keuze vast.`,tags:['inboedel','kostbaarheden','maxima'],bron:''},
 {id:'vzx-172',thema:'verzekeringen',vraag:'Is inboedel buitenshuis verzekerd?',antwoord:`Veel inboedelpolissen bieden een beperkte buitenshuisdekking. Die geldt voor specifieke gebeurtenissen en vaak tot een maximum. Diefstal uit een auto is vaak beperkt of uitgesloten. Controleer de voorwaarden van de verzekeraar.`,tags:['inboedel','buitenshuis','diefstal'],bron:''},
 {id:'vzx-173',thema:'verzekeringen',vraag:'Wat moet een klant doen bij inbraak?',antwoord:`De klant meldt de inbraak bij de politie en bij de verzekeraar. Bewaar sporen en maak foto's. Bewijs van aankoop of eigendom helpt bij de vaststelling. Veel voorwaarden vereisen sporen van braak voor dekking.`,tags:['inboedel','inbraak','schademelding','aangifte'],bron:''},
 {id:'vzx-174',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij inboedeldekking voor thuiswerkende zzp-ers?',antwoord:`Zakelijke inventaris is vaak niet gedekt op de particuliere inboedelpolis. Ook bedrijfsschade valt erbuiten. Een zakelijke inventarisverzekering kan nodig zijn. Vraag naar zakelijk gebruik en leg vast.`,tags:['inboedel','zzp','zakelijk','fouten'],bron:''},
 {id:'vzx-175',thema:'verzekeringen',vraag:'Hoe gaat een opstalpolis om met zonnepanelen?',antwoord:`Zonnepanelen op het dak worden vaak als onderdeel van de woning gezien. Dan vallen ze onder de opstal. Bij huurwoningen of losse installaties kan dat anders zijn. Controleer of de herbouwwaarde de panelen omvat en of de verzekeraar ze apart wil weten.`,tags:['opstal','zonnepanelen','verduurzaming'],bron:''},
 {id:'vzx-176',thema:'verzekeringen',vraag:'Moet de opstal na verduurzaming worden aangepast?',antwoord:`Verduurzaming kan de herbouwwaarde verhogen, bijvoorbeeld door isolatie, warmtepomp of panelen. Dat kan leiden tot onderverzekering. Laat de klant de waarde opnieuw bepalen. Dit speelt ook als de verduurzaming via extra leenruimte is gefinancierd.`,tags:['opstal','verduurzaming','herbouwwaarde'],bron:''},
 {id:'vzx-177',thema:'verzekeringen',vraag:'Is een warmtepomp gedekt op de opstalpolis?',antwoord:`Een vast aangebrachte warmtepomp hoort meestal bij de opstal. Schade door brand of storm is dan gedekt volgens de voorwaarden. Defecten door slijtage of ouderdom zijn meestal uitgesloten. Controleer de voorwaarden van de verzekeraar.`,tags:['opstal','warmtepomp','verduurzaming'],bron:''},
 {id:'vzx-178',thema:'verzekeringen',vraag:'Wat dekt een particuliere aansprakelijkheidsverzekering?',antwoord:`De verzekering dekt schade die de verzekerde als particulier aan anderen toebrengt en waarvoor hij aansprakelijk is. Opzet is uitgesloten. Schade in beroep of bedrijf valt erbuiten. Motorrijtuigen zijn meestal uitgesloten.`,tags:['avp','aansprakelijkheid','particulier'],bron:'BW boek 6'},
 {id:'vzx-179',thema:'verzekeringen',vraag:'Zijn ouders aansprakelijk voor schade door hun kinderen?',antwoord:`Voor kinderen onder 14 jaar zijn ouders risicoaansprakelijk. Voor kinderen van 14 en 15 jaar zijn ouders aansprakelijk, tenzij zij niets te verwijten valt. Vanaf 16 jaar is het kind zelf aansprakelijk. Een AVP dekt in de regel ook inwonende kinderen.`,tags:['avp','kinderen','risicoaansprakelijkheid'],bron:'BW boek 6'},
 {id:'vzx-180',thema:'verzekeringen',vraag:'Is schade door een huisdier gedekt op de AVP?',antwoord:`De bezitter van een dier is risicoaansprakelijk voor schade die het dier aanricht. De AVP dekt deze aansprakelijkheid meestal. Voor bepaalde dieren of bedrijfsmatig gebruik kunnen uitsluitingen gelden. Controleer de voorwaarden van de verzekeraar.`,tags:['avp','dieren','risicoaansprakelijkheid'],bron:'BW boek 6'},
 {id:'vzx-181',thema:'verzekeringen',vraag:'Is schade aan geleende spullen gedekt op de AVP?',antwoord:`Schade aan zaken die de verzekerde onder zich heeft, is vaak beperkt of uitgesloten. Sommige polissen bieden een beperkte dekking. Dat geldt bijvoorbeeld voor geleende of gehuurde spullen. Controleer de voorwaarden van de verzekeraar.`,tags:['avp','opzicht','geleende zaken'],bron:''},
 {id:'vzx-182',thema:'verzekeringen',vraag:'Wie is aansprakelijk voor schade door een gebrekkige woning?',antwoord:`De bezitter van een opstal is risicoaansprakelijk voor schade door een gebrek dat gevaar oplevert. Denk aan een vallende dakpan. Een AVP of opstalpolis dekt dit vaak voor de eigen woning. Bij verhuur kan een aparte dekking nodig zijn.`,tags:['aansprakelijkheid','opstal','risicoaansprakelijkheid'],bron:'BW boek 6'},
 {id:'vzx-183',thema:'verzekeringen',vraag:'Hoe zit het met aansprakelijkheid bij het verhuren van een woning?',antwoord:`Bij verhuur gelden andere risico's dan bij eigen bewoning. De particuliere polis dekt verhuur vaak niet of beperkt. Een verhuurdersaansprakelijkheid of aangepaste opstalpolis kan nodig zijn. Controleer de voorwaarden en meld verhuur aan de verzekeraar.`,tags:['aansprakelijkheid','verhuur','opstal'],bron:''},
 {id:'vzx-184',thema:'verzekeringen',vraag:'Is schade door een zzp-er tijdens werk gedekt op de AVP?',antwoord:`Nee, schade in de uitoefening van beroep of bedrijf valt buiten de AVP. De zzp-er heeft een bedrijfsaansprakelijkheidsverzekering nodig. Bij advieswerk kan een beroepsaansprakelijkheidsverzekering passend zijn. Inventariseer de werkzaamheden en leg dit vast.`,tags:['aansprakelijkheid','zzp','avb','bav'],bron:''},
 {id:'vzx-185',thema:'verzekeringen',vraag:'Wat is het verschil tussen een AVB en een BAV?',antwoord:`Een AVB dekt schade aan personen en zaken door bedrijfsactiviteiten. Een BAV dekt financiële schade door beroepsfouten, zoals verkeerd advies. Voor veel adviesberoepen is een BAV verplicht of gebruikelijk. Bepaal per beroep welke dekking nodig is.`,tags:['aansprakelijkheid','avb','bav'],bron:''},
 {id:'vzx-186',thema:'verzekeringen',vraag:'Moet een financieel adviseur een beroepsaansprakelijkheidsverzekering hebben?',antwoord:`Voor bemiddelaars en adviseurs in verzekeringen geldt een wettelijke eis om de aansprakelijkheid te dekken. Er gelden minimale verzekerde bedragen die periodiek worden aangepast. Raadpleeg de actuele eisen bij de AFM. Controleer ook de dekking voor uitbestede werkzaamheden.`,tags:['bav','adviseur','vergunning'],bron:'Wft'},
 {id:'vzx-187',thema:'verzekeringen',vraag:'Wat is een claims-made dekking bij een BAV?',antwoord:`Bij claims-made is de claim gedekt als deze tijdens de looptijd van de polis wordt ingediend. Het moment van de fout is daarbij minder bepalend. Bij beëindiging kan een uitloopdekking nodig zijn. Controleer de voorwaarden van de verzekeraar.`,tags:['bav','claims-made','uitloop'],bron:''},
 {id:'vzx-188',thema:'verzekeringen',vraag:'Waarom is uitloopdekking belangrijk bij stoppen als adviseur?',antwoord:`Claims over oud advies kunnen na het stoppen nog worden ingediend. Zonder uitloopdekking is de adviseur dan onverzekerd. Regel de uitloop bij beëindiging of overdracht van de portefeuille. Leg de afspraken vast bij de overdracht.`,tags:['bav','uitloop','bedrijfsbeeindiging'],bron:''},
 {id:'vzx-189',thema:'verzekeringen',vraag:'Wat is de opzetclausule bij een AVP?',antwoord:`Schade die opzettelijk is veroorzaakt valt buiten de dekking. Vaak geldt dit ook voor groepsgedrag waarbij iemand meedoet. Voor kinderen kunnen afwijkende regels gelden. Controleer de clausule in de voorwaarden.`,tags:['avp','opzet','uitsluiting'],bron:'BW boek 7'},
 {id:'vzx-190',thema:'verzekeringen',vraag:'Hoe zit het met dubbele verzekering bij aansprakelijkheid?',antwoord:`Als twee polissen hetzelfde risico dekken, kan de verzekerde niet tweemaal vergoed krijgen. Verzekeraars verdelen de schade onderling. Polissen bevatten vaak een clausule dat ze secundair dekken. Voorkom onnodige dubbele premie.`,tags:['aansprakelijkheid','dubbele verzekering','samenloop'],bron:'BW boek 7'},
 {id:'vzx-191',thema:'verzekeringen',vraag:'Wat is een samenloopclausule?',antwoord:`Een samenloopclausule regelt wat er gebeurt als een andere verzekering hetzelfde dekt. De verzekeraar verwijst dan eerst naar de andere polis. Als beide polissen zo een clausule hebben, verdelen verzekeraars de schade. Controleer de voorwaarden van beide polissen.`,tags:['samenloop','dubbele verzekering','polisvoorwaarden'],bron:'BW boek 7'},
 {id:'vzx-192',thema:'verzekeringen',vraag:'Is glasschade gedekt op de opstal of inboedel?',antwoord:`Glas in de woning valt vaak onder de opstal. Sommige polissen hebben een aparte glasdekking. Bij een huurwoning is de huurder soms verantwoordelijk. Controleer de voorwaarden en het huurcontract.`,tags:['glas','opstal','inboedel'],bron:''},
 {id:'vzx-193',thema:'verzekeringen',vraag:'Hoe ga je om met inboedel bij samenwonen?',antwoord:`Bij samenwonen is meestal één inboedelpolis voor het hele huishouden voldoende. Controleer of beide partners als verzekerde zijn opgenomen. Bij twee polissen kan dubbele dekking ontstaan. Pas de verzekerde waarde aan na samenvoegen.`,tags:['inboedel','samenwonen','dubbele verzekering'],bron:''},
 {id:'vzx-194',thema:'verzekeringen',vraag:'Hoe ga je om met inboedel bij een scheiding?',antwoord:`Na een scheiding wonen partners apart en is een eigen inboedelpolis per huishouden nodig. De lopende polis staat vaak op naam van één partner. Regel tijdig nieuwe dekking voor de vertrekkende partner. Leg de afspraken vast.`,tags:['inboedel','scheiding','polishouder'],bron:''},
 {id:'vzx-195',thema:'verzekeringen',vraag:'Is de inboedel verzekerd van een student die op kamers woont?',antwoord:`Sommige inboedelpolissen dekken de spullen van uitwonende studerende kinderen beperkt mee. Er gelden vaak maxima en voorwaarden. Een eigen polis kan nodig zijn. Controleer de voorwaarden van de verzekeraar.`,tags:['inboedel','student','uitwonend'],bron:''},
 {id:'vzx-196',thema:'verzekeringen',vraag:'Wat doe je als een klant een vakantiewoning in het buitenland bezit?',antwoord:`Een Nederlandse opstalpolis dekt een woning in het buitenland meestal niet. Vaak is een lokale verzekering nodig. Ook aansprakelijkheid en verhuur vragen aandacht. Verwijs zo nodig naar een specialist en leg vast.`,tags:['opstal','buitenland','vakantiewoning'],bron:''},
 {id:'vzx-197',thema:'verzekeringen',vraag:'Wat is het risico van een recreatiewoning die wordt verhuurd?',antwoord:`Bij verhuur gelden vaak andere premies en voorwaarden. Schade door huurders is niet altijd gedekt. De verzekeraar moet de verhuur weten. Controleer de voorwaarden en leg vast dat de klant de verhuur meldt.`,tags:['opstal','recreatiewoning','verhuur'],bron:''},
 {id:'vzx-198',thema:'verzekeringen',vraag:'Is schade door een lekkage bij de bovenburen gedekt?',antwoord:`Schade aan de eigen inboedel valt meestal onder de eigen inboedelpolis. Schade aan het gebouw valt meestal onder de opstalpolis, bij een appartement die van de VvE. De verzekeraar kan verhalen op een aansprakelijke partij. Meld de schade bij de eigen verzekeraar.`,tags:['waterschade','lekkage','vve','verhaal'],bron:''},
 {id:'vzx-199',thema:'verzekeringen',vraag:'Wat is verhaal en wat merkt de klant ervan?',antwoord:`Na uitkering kan de verzekeraar de schade verhalen op degene die aansprakelijk is. De klant hoeft daar meestal niets voor te doen. Het eigen risico kan de klant soms zelf bij de aansprakelijke partij claimen. Een verhaalsrechtsbijstandsdekking kan helpen bij persoonlijke schade.`,tags:['verhaal','schadebehandeling','subrogatie'],bron:'BW boek 7'},
 {id:'vzx-200',thema:'verzekeringen',vraag:'Welke documenten adviseer je een klant te bewaren voor een eventuele inboedelschade?',antwoord:`Bewaar aankoopbonnen, garantiebewijzen en facturen van waardevolle spullen. Foto's of een video van de inboedel helpen bij het aantonen van bezit. Bewaar deze gegevens ook buiten de woning, bijvoorbeeld digitaal. Taxatierapporten van kostbaarheden horen daar ook bij.`,tags:['inboedel','bewijs','schadebehandeling'],bron:''},
 {id:'vzx-201',thema:'verzekeringen',vraag:'Hoe lang heeft een verzekerde om een schade te melden?',antwoord:`De verzekerde moet de schade melden zodra hij die kent of redelijkerwijs kan kennen. Te late melding leidt alleen tot verval van dekking als de verzekeraar daardoor in zijn belangen is geschaad. Bij opzet tot misleiding kan het recht vervallen. Adviseer altijd direct melden.`,tags:['schademelding','termijn','meldingsplicht'],bron:'BW boek 7'},
 {id:'vzx-202',thema:'verzekeringen',vraag:'Wanneer verjaart een vordering tot uitkering op een verzekering?',antwoord:`De vordering verjaart in de regel drie jaar na het moment dat de verzekerde de opeisbaarheid kent. Een schriftelijke melding of aanspraak kan de verjaring stuiten. Na een ondubbelzinnige afwijzing door de verzekeraar loopt een kortere termijn. Wijs de klant op deze termijn bij een afwijzing.`,tags:['verjaring','schadebehandeling','afwijzing'],bron:'BW boek 7'},
 {id:'vzx-203',thema:'verzekeringen',vraag:'Wat is de bereddingsplicht?',antwoord:`De verzekerde moet na een schadevoorval maatregelen nemen om de schade te beperken. Denk aan het afdekken van een lekkend dak. De redelijke kosten daarvan vergoedt de verzekeraar, ook boven de verzekerde som. Bewaar de bonnen van die kosten.`,tags:['beredding','schadebeperking','kosten'],bron:'BW boek 7'},
 {id:'vzx-204',thema:'verzekeringen',vraag:'Wat betekent het indemniteitsbeginsel?',antwoord:`Een schadeverzekering mag de verzekerde niet rijker maken dan voor de schade. Er wordt dus niet meer vergoed dan het werkelijke verlies. Bij sommenverzekeringen, zoals een ORV, geldt dit beginsel niet. Dit verklaart verschillen in uitkering tussen polissoorten.`,tags:['indemniteit','schadeverzekering','sommenverzekering'],bron:'BW boek 7'},
 {id:'vzx-205',thema:'verzekeringen',vraag:'Wanneer mag een verzekeraar een uitkering weigeren wegens opzet of roekeloosheid?',antwoord:`De verzekeraar keert niet uit aan een verzekerde die de schade met opzet of door roekeloosheid heeft veroorzaakt. Roekeloosheid is meer dan gewone onvoorzichtigheid. De verzekeraar moet dit aantonen. Bij twijfel kan de klant de afwijzing laten toetsen.`,tags:['opzet','roekeloosheid','afwijzing'],bron:'BW boek 7'},
 {id:'vzx-206',thema:'verzekeringen',vraag:'Wat gebeurt er met de dekking als de premie niet wordt betaald?',antwoord:`De verzekeraar moet de verzekeringnemer eerst aanmanen. Na een termijn in die aanmaning kan de dekking worden geschorst. Schade tijdens de schorsing is dan niet gedekt. Na betaling herleeft de dekking meestal voor nieuwe schades.`,tags:['premieachterstand','aanmaning','schorsing'],bron:'BW boek 7'},
 {id:'vzx-207',thema:'verzekeringen',vraag:'Mag een consument een schadeverzekering op elk moment opzeggen?',antwoord:`Na de eerste contractsperiode is een consumentenverzekering die stilzwijgend is verlengd in de regel op elk moment opzegbaar. Er geldt een opzegtermijn van ten hoogste één maand. In de eerste contractsperiode gelden de voorwaarden. Controleer de voorwaarden van de verzekeraar.`,tags:['opzeggen','stilzwijgende verlenging','consument'],bron:'BW boek 7'},
 {id:'vzx-208',thema:'verzekeringen',vraag:'Mag een verzekeraar de voorwaarden tussentijds eenzijdig wijzigen?',antwoord:`Dat kan alleen als de polis een wijzigingsclausule bevat. De verzekeringnemer heeft dan vaak het recht de polis te beëindigen als hij het niet eens is. Een collectieve herziening is daar een voorbeeld van. Informeer de klant tijdig over de gevolgen.`,tags:['polisvoorwaarden','wijzigingsclausule','opzeggen'],bron:''},
 {id:'vzx-209',thema:'verzekeringen',vraag:'Welke voorwaarden gelden: die bij afsluiten of de actuele?',antwoord:`In principe gelden de voorwaarden die bij de polis horen en die aan de klant zijn verstrekt. Wijzigingen werken alleen als die rechtsgeldig zijn doorgevoerd. Bewaar daarom altijd de geldende voorwaarden in het dossier. Bij schade beoordeel je de polis op de voorwaarden van dat moment.`,tags:['polisvoorwaarden','dossier','schade'],bron:''},
 {id:'vzx-210',thema:'verzekeringen',vraag:'Wat is de contra proferentem-regel?',antwoord:`Bij onduidelijke voorwaarden in een consumentenovereenkomst geldt de voor de consument gunstigste uitleg. Dat staat in het burgerlijk recht. Het is relevant bij geschillen over dekking. Verwijs bij twijfel naar een juridische beoordeling.`,tags:['polisvoorwaarden','uitleg','consument'],bron:'BW boek 6'},
 {id:'vzx-211',thema:'verzekeringen',vraag:'Wat is het verschil tussen een uitsluiting en een clausule op het polisblad?',antwoord:`Een uitsluiting in de algemene voorwaarden geldt voor alle verzekerden. Een clausule op het polisblad is afgestemd op deze klant. Clausules gaan vaak voor de algemene voorwaarden. Lees beide en bespreek bijzondere clausules met de klant.`,tags:['polisvoorwaarden','clausule','uitsluiting'],bron:''},
 {id:'vzx-212',thema:'verzekeringen',vraag:'Wat doet een schade-expert?',antwoord:`Een schade-expert stelt de oorzaak en omvang van de schade vast. De verzekeraar schakelt de expert meestal in. De klant kan een eigen contra-expert inschakelen. Bij gedekte schade vergoedt de verzekeraar de kosten van de contra-expert vaak tot een redelijk bedrag.`,tags:['schade-expert','contra-expert','schadebehandeling'],bron:''},
 {id:'vzx-213',thema:'verzekeringen',vraag:'Wanneer is een contra-expert verstandig?',antwoord:`Een contra-expert is zinvol bij grote of complexe schade. Ook bij onenigheid over de oorzaak of het bedrag kan dit helpen. De klant krijgt daarmee een eigen deskundige. Controleer in de voorwaarden welke kosten worden vergoed.`,tags:['contra-expert','schadebehandeling','geschil'],bron:''},
 {id:'vzx-214',thema:'verzekeringen',vraag:'Wat is de rol van de adviseur bij schadebehandeling?',antwoord:`De adviseur helpt de klant bij het melden en volgen van de schade. Hij controleert de beoordeling aan de hand van de voorwaarden. Bij een volmacht kan hij de schade zelf afhandelen. Leg contact en uitkomsten vast in het dossier.`,tags:['schadebehandeling','rol adviseur','volmacht'],bron:''},
 {id:'vzx-215',thema:'verzekeringen',vraag:'Wat is een volmacht in verzekeringen?',antwoord:`Bij een volmacht mag een tussenpersoon namens de verzekeraar polissen accepteren of schades afhandelen. Dat vraagt aparte afspraken en vaak een aparte vergunning. De volmachtgever blijft verantwoordelijk. Controleer de grenzen van de volmacht.`,tags:['volmacht','tussenpersoon','schadebehandeling'],bron:'Wft'},
 {id:'vzx-216',thema:'verzekeringen',vraag:'Wat doe je als de klant het niet eens is met een schadeafwijzing?',antwoord:`Vraag de verzekeraar om een schriftelijke motivering. Toets de afwijzing aan de voorwaarden. Dien zo nodig een klacht in bij de interne klachtenprocedure. Daarna kan de klant naar Kifid of de rechter.`,tags:['afwijzing','klacht','kifid'],bron:'Kifid'},
 {id:'vzx-217',thema:'verzekeringen',vraag:'Welke verzekeringsgeschillen kan een consument aan Kifid voorleggen?',antwoord:`Een consument kan geschillen met een verzekeraar of adviseur voorleggen, zoals een afgewezen claim of een betwiste uitleg van de voorwaarden. Eerst moet de interne klachtenprocedure zijn doorlopen. De verzekeraar of adviseur moet bij Kifid zijn aangesloten. Controleer de actuele termijnen en voorwaarden bij Kifid.`,tags:['kifid','klacht','consument'],bron:'Kifid'},
 {id:'vzx-218',thema:'verzekeringen',vraag:'Hoe moet een adviseur omgaan met een klacht over zijn eigen advies?',antwoord:`Neem de klacht serieus en registreer deze. Volg de interne klachtenprocedure binnen de afgesproken termijnen. Informeer de beroepsaansprakelijkheidsverzekeraar als er een claim dreigt. Wijs de klant op de mogelijkheid van Kifid.`,tags:['klacht','adviseur','klachtenprocedure','bav'],bron:'Wft'},
 {id:'vzx-219',thema:'verzekeringen',vraag:'Wat is doorlopende zorgplicht bij verzekeringen?',antwoord:`Na het afsluiten blijft de adviseur in bepaalde gevallen verplicht de klant te informeren. Dat hangt af van de afspraken in de dienstverlening. Bij wijzigingen die de klant raken, kan een actieplicht ontstaan. Leg de afspraken over nazorg duidelijk vast.`,tags:['zorgplicht','nazorg','doorlopend'],bron:'Wft'},
 {id:'vzx-220',thema:'verzekeringen',vraag:'Moet een adviseur een klant waarschuwen als een polis door een levensgebeurtenis niet meer past?',antwoord:`Dat hangt af van de afgesproken dienstverlening en wat de adviseur weet. Is de adviseur op de hoogte van de gebeurtenis, dan ligt actie voor de hand. Een periodieke check maakt dit beter beheersbaar. Leg vast welke signalen je hebt ontvangen en wat je hebt gedaan.`,tags:['zorgplicht','levensgebeurtenis','nazorg'],bron:'Wft'},
 {id:'vzx-221',thema:'verzekeringen',vraag:'Wat is de informatieplicht van een adviseur bij verzekeringen?',antwoord:`De adviseur moet de klant tijdig, juist en begrijpelijk informeren over het product en de dienstverlening. Dat omvat de kosten, de dekking en belangrijke uitsluitingen. Productinformatie moet tijdig voor het afsluiten worden verstrekt. Leg vast welke documenten zijn verstrekt.`,tags:['informatieplicht','productinformatie','zorgplicht'],bron:'Wft'},
 {id:'vzx-222',thema:'verzekeringen',vraag:'Wat is het ken-uw-klantprincipe bij verzekeringsadvies?',antwoord:`De adviseur moet informatie inwinnen over financiële positie, kennis, ervaring, doelstellingen en risicobereidheid. Het advies moet daarop aansluiten. Zonder voldoende informatie kan geen passend advies worden gegeven. Leg de inventarisatie vast.`,tags:['ken uw klant','inventarisatie','passend advies'],bron:'Wft'},
 {id:'vzx-223',thema:'verzekeringen',vraag:'Wat moet een adviseur doen als een klant informatie weigert te geven?',antwoord:`Leg uit waarom de informatie nodig is. Zonder informatie kan het advies beperkt of niet passend zijn. Leg de weigering en de gevolgen vast. Overweeg of advies op dat onderwerp nog verantwoord is.`,tags:['zorgplicht','informatie weigeren','dossier'],bron:'Wft'},
 {id:'vzx-224',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout in een verzekeringsdossier?',antwoord:`Een veelgemaakte fout is dat alleen het product is vastgelegd en niet de afweging. Een toezichthouder of rechter wil zien waarom een keuze passend was. Ook ontbrekende klantbevestigingen komen vaak voor. Gebruik een vaste opbouw voor elk adviesrapport.`,tags:['dossier','fouten','vastlegging'],bron:'AFM'},
 {id:'vzx-225',thema:'verzekeringen',vraag:'Hoe lang moet een adviseur dossiers bewaren?',antwoord:`Bewaar dossiers in elk geval zo lang als wettelijke en fiscale termijnen vereisen. Houd ook rekening met verjaringstermijnen bij mogelijke claims. Dat kan langer zijn dan de wettelijke minimale bewaartermijn. Stem het bewaarbeleid af met de AVG-eisen.`,tags:['dossier','bewaartermijn','avg'],bron:''},
 {id:'vzx-226',thema:'verzekeringen',vraag:'Hoe ga je om met medische gegevens van een klant?',antwoord:`Medische gegevens zijn bijzondere persoonsgegevens. Een adviseur verwerkt ze alleen als dat noodzakelijk is. In de praktijk gaan gezondheidsverklaringen rechtstreeks naar de medisch adviseur van de verzekeraar. Leg vast hoe je dit hebt geregeld.`,tags:['medische gegevens','privacy','avg'],bron:'AVG'},
 {id:'vzx-227',thema:'verzekeringen',vraag:'Wat is het PARP-proces en wat betekent het voor adviseurs?',antwoord:`Verzekeraars moeten producten toetsen op de belangen van de doelgroep. Dat gebeurt in het productontwikkelings- en beoordelingsproces. De verzekeraar bepaalt een doelmarkt. De adviseur moet nagaan of de klant tot die doelmarkt behoort.`,tags:['parp','doelmarkt','productontwikkeling'],bron:'Wft'},
 {id:'vzx-228',thema:'verzekeringen',vraag:'Wat doe je als een klant buiten de doelmarkt van een product valt?',antwoord:`Advisering buiten de doelmarkt is niet per se verboden, maar vraagt extra onderbouwing. Leg uit waarom het product toch passend is. Geef de verzekeraar zo nodig feedback. Leg de afweging vast.`,tags:['doelmarkt','parp','onderbouwing'],bron:'Wft'},
 {id:'vzx-229',thema:'verzekeringen',vraag:'Hoe ga je om met een polis die de klant zelf heeft afgesloten zonder advies?',antwoord:`Bij een eerste gesprek beoordeel je ook de bestaande polissen. De adviseur is niet aansprakelijk voor de keuze bij afsluiten. Signaleer wel duidelijke risico's en leg dit vast. Spreek af of de polis in je dienstverlening valt.`,tags:['bestaande polis','execution only','inventarisatie'],bron:''},
 {id:'vzx-230',thema:'verzekeringen',vraag:'Welk risico loopt een klant bij het verhogen van een bestaande dekking?',antwoord:`Na een wijziging kan de verzekeraar soms een nieuwe toets doen, zoals bij verhoging van de dekking. Het risico op nieuwe uitsluitingen of premie is dan reëel. Laat de klant dit vooraf afwegen. Controleer de voorwaarden van de verzekeraar.`,tags:['wijziging','verhoging','acceptatie'],bron:''},
 {id:'vzx-231',thema:'verzekeringen',vraag:'Hoe voorkom je dat een klant onverzekerd raakt bij overstap van verzekeraar?',antwoord:`Laat de nieuwe polis ingaan op de dag dat de oude stopt. Zeg de oude polis pas op na acceptatie van de nieuwe. Let op wachttijden en uitsluitingen in de nieuwe polis. Leg de data en bevestigingen vast.`,tags:['overstap','dekking','opzeggen'],bron:''},
 {id:'vzx-232',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij het overstappen van een schadeverzekering?',antwoord:`Een veelgemaakte fout is dat de nieuwe polis andere uitsluitingen of lagere maxima heeft. De klant denkt gelijkwaardig verzekerd te zijn. Ook een lopende schade bij de oude verzekeraar kan problemen geven. Vergelijk de voorwaarden en leg de vergelijking vast.`,tags:['overstap','fouten','schadeverzekering'],bron:''},
 {id:'vzx-233',thema:'verzekeringen',vraag:'Hoe adviseer je over de hoogte van het eigen risico?',antwoord:`Een hoger eigen risico verlaagt de premie. De klant moet het eigen risico bij schade kunnen betalen. Kijk naar buffers en schadeverleden. Leg de afweging vast.`,tags:['eigen risico','premie','afweging'],bron:''},
 {id:'vzx-234',thema:'verzekeringen',vraag:'Wat is fraude in verzekeringen en wat zijn de gevolgen?',antwoord:`Fraude is het bewust geven van onjuiste informatie om een uitkering of polis te krijgen. De verzekeraar kan de uitkering weigeren, de polis beëindigen en de gegevens registreren. Ook aangifte bij de politie is mogelijk. Wijs de klant op het belang van juiste informatie.`,tags:['fraude','gevolgen','registratie'],bron:'Verbond van Verzekeraars'},
 {id:'vzx-235',thema:'verzekeringen',vraag:'Wat moet een adviseur doen bij een vermoeden van fraude door een klant?',antwoord:`Werk niet mee aan het indienen van onjuiste informatie. Bespreek het vermoeden met de klant en leg dit vast. Raadpleeg de interne procedures en zo nodig een jurist. Integriteit staat voorop in de dienstverlening.`,tags:['fraude','integriteit','adviseur'],bron:'Wft'},
 {id:'vzx-236',thema:'verzekeringen',vraag:'Wat is het belang van de polisdatum bij een schade?',antwoord:`Een schade moet in de regel na ingangsdatum en voor einddatum hebben plaatsgevonden. Schade die al bestond bij ingang is meestal uitgesloten. Bij aansprakelijkheid kan het moment van de claim of de gebeurtenis bepalend zijn. Controleer de voorwaarden van de verzekeraar.`,tags:['polisdatum','schade','dekkingsperiode'],bron:''},
 {id:'vzx-237',thema:'verzekeringen',vraag:'Wat is een onzekerheidsvereiste bij verzekeringen?',antwoord:`Een verzekering dekt alleen schade die bij het sluiten onzeker was. Schade die al was ontstaan of zeker zou ontstaan valt buiten de dekking. Dit staat in het verzekeringsrecht. Bespreek bekende gebreken bij het afsluiten.`,tags:['onzekerheidsvereiste','verzekeringsrecht'],bron:'BW boek 7'},
 {id:'vzx-238',thema:'verzekeringen',vraag:'Hoe ga je om met een schade die zich geleidelijk ontwikkelt?',antwoord:`Geleidelijk ontstane schade, zoals vocht of schimmel, is vaak uitgesloten. Dekking geldt meestal voor plotselinge en onvoorziene schade. De oorzaak bepaalt de dekking. Laat de klant zo snel mogelijk melden.`,tags:['geleidelijke schade','uitsluiting','oorzaak'],bron:''},
 {id:'vzx-239',thema:'verzekeringen',vraag:'Waarom is beeldmateriaal belangrijk bij een schademelding?',antwoord:`Foto's leggen de situatie vast voordat er wordt hersteld. Dat helpt de verzekeraar bij het vaststellen van oorzaak en omvang. Ruim beschadigde zaken pas op na overleg met de verzekeraar. Adviseer de klant dit standaard te doen.`,tags:['schademelding','bewijs','foto'],bron:''},
 {id:'vzx-240',thema:'verzekeringen',vraag:'Mag een klant zelf een herstelbedrijf kiezen?',antwoord:`Dat hangt af van de voorwaarden. Sommige verzekeraars werken met een eigen netwerk van herstellers. Kiest de klant een ander, dan kan de vergoeding lager zijn. Controleer de voorwaarden van de verzekeraar.`,tags:['herstel','herstelbedrijf','schadebehandeling'],bron:''},
 {id:'vzx-241',thema:'verzekeringen',vraag:'Hoe werkt de vergoeding van schade in natura?',antwoord:`Bij vergoeding in natura laat de verzekeraar de schade herstellen of vervangen in plaats van geld uit te keren. Dat kan sneller en efficiënter zijn. De klant heeft minder keuzevrijheid. Bespreek de mogelijkheden bij de schademelding.`,tags:['natura','vergoeding','herstel'],bron:''},
 {id:'vzx-242',thema:'verzekeringen',vraag:'Wat is een eigen risico per gebeurtenis?',antwoord:`Bij een eigen risico per gebeurtenis geldt het bedrag voor iedere schade afzonderlijk. Bij meerdere schades in een jaar telt het eigen risico meerdere keren. Dit verschilt van een eigen risico per jaar. Lees de definitie in de voorwaarden.`,tags:['eigen risico','gebeurtenis','polisvoorwaarden'],bron:''},
 {id:'vzx-243',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij het lezen van polisvoorwaarden?',antwoord:`Een veelgemaakte fout is alleen naar de dekkingsomschrijving kijken. De begripsbepalingen en uitsluitingen bepalen de echte reikwijdte. Ook bijzondere voorwaarden op het polisblad worden gemist. Lees de documenten in samenhang.`,tags:['polisvoorwaarden','begripsbepalingen','fouten'],bron:''},
 {id:'vzx-244',thema:'verzekeringen',vraag:'Hoe ga je om met een klant die meerdere polissen bij verschillende adviseurs heeft?',antwoord:`Breng in kaart welke polissen er zijn en wie welke beheert. Spreek af voor welke polissen jij verantwoordelijk bent. Signaleer dubbele dekkingen of gaten. Leg de afbakening vast in de dienstverleningsovereenkomst.`,tags:['inventarisatie','afbakening','meerdere adviseurs'],bron:''},
 {id:'vzx-245',thema:'verzekeringen',vraag:'Wat is een veelgemaakte fout bij het overnemen van een klantportefeuille?',antwoord:`Een veelgemaakte fout is dat oude dossiers en afspraken niet volledig worden overgedragen. De nieuwe adviseur kent dan de eerdere afwegingen niet. Ook lopende schades of klachten kunnen ontbreken. Controleer dossiers bij overname en leg de overdracht vast.`,tags:['portefeuille','overname','fouten'],bron:''},
 {id:'vzx-246',thema:'verzekeringen',vraag:'Hoe leg je een adviesgesprek over verzekeringen goed vast?',antwoord:`Gebruik een gespreksverslag met inventarisatie, analyse, advies en keuze van de klant. Vermeld datum, aanwezigen en verstrekte documenten. Laat de klant het verslag ontvangen en bevestigen. Bewaar het verslag in het dossier.`,tags:['gespreksverslag','vastlegging','dossier'],bron:'Wft'},
 {id:'vzx-247',thema:'verzekeringen',vraag:'Mag een adviseur een polis aanvragen op basis van een mondelinge opdracht?',antwoord:`Een mondelinge opdracht kan, maar is lastig te bewijzen. Leg de opdracht daarom schriftelijk vast of bevestig deze per e-mail. Verzekeraars vragen voor veel producten een handtekening van de klant. Bewaar de bevestiging in het dossier.`,tags:['opdracht','bevestiging','dossier'],bron:''},
 {id:'vzx-248',thema:'verzekeringen',vraag:'Hoe ga je om met een verzekering na overlijden van de verzekeringnemer?',antwoord:`Schadeverzekeringen zoals opstal en inboedel lopen meestal door voor de erfgenamen. De verzekeraar moet worden geïnformeerd. Wijzig de verzekeringnemer en controleer of de dekking nog past. Bij leegstand van de woning gelden vaak beperkingen.`,tags:['overlijden','schadeverzekering','erfgenamen'],bron:''},
 {id:'vzx-249',thema:'verzekeringen',vraag:'Waarom is het schadeverleden belangrijk bij het afsluiten van een nieuwe polis?',antwoord:`Verzekeraars vragen naar eerdere schades en opzeggingen door verzekeraars. Dat valt onder de mededelingsplicht. Een onjuist antwoord kan later tot afwijzing van een claim leiden. Laat de klant deze vragen zorgvuldig beantwoorden.`,tags:['schadeverleden','mededelingsplicht','acceptatie'],bron:'BW boek 7'},
 {id:'vzx-250',thema:'verzekeringen',vraag:'Wat is het verschil tussen een gedekte gebeurtenis en een gedekte oorzaak?',antwoord:`Sommige polissen omschrijven de dekking naar gebeurtenis, zoals brand of storm. Uitsluitingen kijken vaak naar de oorzaak, zoals slijtage of constructiefouten. Een schade kan dus onder een gedekte gebeurtenis vallen en toch door de oorzaak zijn uitgesloten. Lees dekking en uitsluitingen in samenhang.`,tags:['polisvoorwaarden','gebeurtenis','oorzaak'],bron:''}
]);
